L2_1.m_StartFXSoundName = "FX_CUTSCEN_CROWD_NOISE_05"
L2_1.m_Talk_KOREA = "보안국은 건국기념전당 앞에서 발생한 폭발 사고가 반정부 단체인 <color=#ffd34c>순혈지식 연대</color>의 계획적인 사보타주라고 발표했습니다."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "保安局は、建国記念館の前で発生した爆発事故が反政府団体である<color=#ffd34c>純血知識連帯</color>の計画的なサボタージュだと発表しました。"
L2_1.m_Talk_ENG = "The Department of National Security has announced that the explosion in front of the National Foundation Hall was a terrorist attack planned by the anti-government organization <color=#ffd34c>Pureblood Knowledge Regiment</color>"
L2_1.m_Talk_TWN = "安全局表示，於建國紀念堂前發生的爆炸事件，是反政府團體 <color=#ffd34c>純血知識年代</color>有計畫性的攻擊行動。"
L2_1.m_Talk_THA = "สำนักงานความมั่นคงแห่งชาติออกมาประกาศว่าเหตุระเบิดที่หน้าหอสถาปนาแห่งชาติ\nเป็นการก่อการร้ายฝีมือองค์กรต่อต้านรัฐบาลในนาม<color=#ffd34c>กองทหารเลือดบริสุทธิ์</color>"
L2_1.m_Talk_VTN = "Cục An Ninh Quốc Gia đã thông báo rằng vụ nổ trước Hội trường Thành lập Quốc gia là một cuộc tấn công khủng bố được lên kế hoạch bởi tổ chức chống chính phủ <color=#ffd34c>Trung đoàn Kiến Thức Thuần Huyết</color>"
L2_1.m_Talk_SCN = "安全局公开发表声明，称建国纪念堂前面发生的爆炸事故是反政府团体<color=#ffd34c>纯血知识会</color>有计划性的破坏行为。"
L2_1.m_Talk_DEU = "Die Abteilung für nationale Sicherheit hat verkündet, dass die Explosion vor dem Palast der Gründung ein Terroranschlag war, der von der extremistischen Gruppierung <color=#ffd34c>Verbindung des Reinen Wissens</color> geplant wurde."
L2_1.m_Talk_FRA = "Dans un récent communiqué, le Bureau de la sécurité nationale a annoncé que l'explosion ayant eu lieu devant la Fondation nationale était une attaque terroriste planifiée par l'organisation anti-gouvernementale l'<color=#ffd34c>Ordre des Sang-pur</color>."
L3_1 = {}
L3_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@3#Talk"
L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 4100301
L3_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Talk_KOREA = "건국절 기념 공연의 관객들을 노린 이 사고로 인해 수백 명의 사망자가 발생하였으며……."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "建国記念公演の観客を狙ったこの事件により、数百人が死亡し……"
L3_1.m_Talk_ENG = "Hundreds of people in attendance at the National Foundation Day event were killed.…."
L3_1.m_Talk_TWN = "此次的攻擊，造成數百位來欣賞國慶表演的觀眾死亡……"
L3_1.m_Talk_THA = "ผู้คนนับร้อยที่มาร่วมงานวันสถาปนาแห่งชาติเสียชีวิต..."
L3_1.m_Talk_VTN = "Hàng trăm người tham dự sự kiện Ngày Thành Lập Quốc Gia đã thiệt mạng.…."
L3_1.m_Talk_SCN = "在该次事故中，出现了数百名的伤亡者，其中大部分为前来观看建国节纪念演出的市民观众……"
L3_1.m_Talk_DEU = "Hunderte von Menschen, die bei der Aufführung zum Nationalen Gründungstag anwesend waren, wurden getötet ..."
L3_1.m_Talk_FRA = "Des centaines de personnes venues assister au concert prévu pour célébrer l'anniversaire de la fondation du pays ont été tuées..."
