L8_1.m_StartFXSoundControl = "NCSC_LOOP_PLAY"
L8_1.m_StartFXSoundName = "FX_CUTSCEN_CROWD_NOISE_02"
L8_1.m_Talk_KOREA = "지난번 사태에 휘말렸던 음악가, 루이제 슈나이더 씨의 의식이 회복되었다는 소식입니다."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "以前の事態に巻き込まれた音楽家、ルイーゼ・シュナイダー氏が意識を取り戻しました。"
L8_1.m_Talk_ENG = "It is reported that Louise Schneider, a famous musician who attended the performance, has regained consciousness."
L8_1.m_Talk_TWN = "捲入上次事件的音樂家 露易絲·修奈德，據說已經恢復意識。"
L8_1.m_Talk_THA = "มีรายงานว่าลูอิส ชไนเดอร์ นักดนตรีชื่อดังที่เข้าชมการแสดงเพิ่งได้สติ"
L8_1.m_Talk_VTN = "Có thông tin cho rằng Louise Schneider, một nhạc sĩ nổi tiếng tham dự buổi biểu diễn, đã tỉnh lại."
L8_1.m_Talk_SCN = "据最新消息，被卷入上次事件的音乐家路易丝·施耐德目前已经恢复了意识。"
L8_1.m_Talk_DEU = "Es wird berichtet, dass Louise Schneider, eine berühmte Musikerin, die an der Aufführung teilnahm, wieder das Bewusstsein erlangt hat."
L8_1.m_Talk_FRA = "On rapporte également que Louise Schneider, une célèbre musicienne qui assistait au spectacle, a repris connaissance."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 4100301
L9_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "주치의는 슈나이더 씨가 중추신경 손상으로 하반신이 마비되었다고 전해, 반정부 단체에 대한 국민의 공분을 불러일으킨 바 있습니다."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "主治医はシュナイダー氏が中枢神経の損傷で下半身が麻痺した事実を伝え、反政府団体への国民の怒りを呼び起こしました。"
L9_1.m_Talk_ENG = "The doctors say she has been paralyzed from the waist down, sparking public outrage towards the anti-government forces."
L9_1.m_Talk_TWN = "主治醫生表示，修奈德的中樞神經受損，導致下半身麻痺。而反政府團體的作為，已經引發全國人民的憤怒。"
L9_1.m_Talk_THA = "แพทย์บอกว่าเธอเป็นอัมพาตตั้งแต่เอวลงไป นั่นทำให้ความโกรธแค้นที่สาธารณชนมีต่อกองกำลังต่อต้านรัฐบาลปะทุขึ้น"
L9_1.m_Talk_VTN = "Các bác sĩ cho biết cô đã bị liệt từ thắt lưng trở xuống, làm dấy lên sự phẫn nộ của công chúng đối với lực lượng chống chính phủ."
L9_1.m_Talk_SCN = "主治医生说施耐德小姐因为中枢神经系统损伤，导致下半身瘫痪。这引发了国民对反政府团体的公愤。"
L9_1.m_Talk_DEU = "Die Ärzte sagen, sie sei aufgrund einer zentralen Nervenschädigung von der Taille abwärts gelähmt worden, was die öffentliche Empörung gegenüber den extremistischen Regierungsgruppen ausgelöst hat."
L9_1.m_Talk_FRA = "Les médecins disent qu'elle a perdu l'usage de ses deux jambes, une nouvelle qui n'a pas manqué de provoquer une indignation générale à l'égard des forces rebelles."
