L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Talk_KOREA = "뉴스 중의 뉴스, 진짜 뉴스를 전하는 <color=#ffd34c>국민의 노래</color>."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "ニュースの中のニュース、本当のニュースをお伝えする<color=#ffd34c>民の歌</color>。"
L16_1.m_Talk_ENG = "The news of the news! <color=#ffd34c>The Voice of the People</color>, reporting the real truth."
L16_1.m_Talk_TWN = "重磅新聞，只報導真正新聞的<color=#ffd34c>人民之聲</color>。"
L16_1.m_Talk_THA = "ที่สุดเหนือทุกข่าว! <color=#ffd34c>เสียงประชาชน</color> เรารายงานแต่ความจริงแท้"
L16_1.m_Talk_VTN = "Tin tức mới nhất! <color=#ffd34c>Tiếng nói của Nhân dân</color>, truyền tải sự thật."
L16_1.m_Talk_SCN = "哈喽！NetTube的朋友们！这里是新闻中的新闻，只播报真实新闻的<color=#ffd34c>国民之声</color>！"
L16_1.m_Talk_DEU = "Die Nachrichten der Nachrichten! <color=#ffd34c>Die Stimme der Bevölkerung</color>, die die wahren Nachrichten vermittelt."
L16_1.m_Talk_FRA = "Restez au cœur de l'actu avec <color=#ffd34c>La voix du peuple</color>, le seul media qui ne vous ment pas !"
L17_1 = {}
L17_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 4100301
L17_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Talk_KOREA = "오늘 영상에서는 현장에서 살아남은 슈나이더 모녀에 대해 다루고자 합니다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "今日の動画では、現場で生き残ったシュナイダー親子について話します。"
L17_1.m_Talk_ENG = "In today's video, we're going to break down the news on two survivors, Louis Schneider and her daughter."
L17_1.m_Talk_TWN = "今天想要討論的內容，是有關於在爆炸事件中倖存下來的修奈德母女。"
L17_1.m_Talk_THA = "ในวิดีโอวันนี้ เราจะลงรายละเอียดในข่าวกับสองผู้รอดชีวิต ลูอิส ชไนเดอร์ กับลูกสาวของเธอ"
L17_1.m_Talk_VTN = "Trong video ngày hôm nay, chúng ta sẽ chia sẻ tin tức về hai người sống sót, Louis Schneider và con gái của cô ấy."
L17_1.m_Talk_SCN = "今天我们为大家带来的是在爆炸现场幸存下来的施耐德母女的近况。"
L17_1.m_Talk_DEU = "In dem heutigen Video geht es um Louise Schneider und ihre Tochter, die beide den Anschlag überlebt haben."
L17_1.m_Talk_FRA = "Dans la vidéo d'aujourd'hui, nous allons vous parler des deux miraculées de l'attentat, la célèbre musicienne Louise Schneider et sa fille."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 4100301
L18_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Talk_KOREA = "이번 내용, 끝까지 봐도 후회 안 하실 겁니다. 다 보시고 난 뒤 구독과 좋아요 잊지 마세요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "今回の内容、最後まで見ても後悔はしないはずです。視聴後、チャンネル登録とイイね！をお忘れなく。"
L18_1.m_Talk_ENG = "You’ll regret it if you don’t watch till the end! And don’t forget to like and subscribe for amazing content!"
L18_1.m_Talk_TWN = "一定要看到最後，保證你不會後悔！看完後別忘記按讚加訂閱喔！"
L18_1.m_Talk_THA = "คุณจะต้องเสียใจถ้าไม่ดูให้จบ! และอย่าลืมกดถูกใจและติดตามเพื่อรับชมเนื้อหาชั้นยอด!"
L18_1.m_Talk_VTN = "Bạn sẽ hối tiếc nếu không xem đến cuối cùng! Và đừng quên like và subscribe cho những nội dung hấp dẫn nhé!"
L18_1.m_Talk_SCN = "这次的内容不看到最后，你一定会后悔！要是觉得这一期内容赞爆的话，不要忘了一键三连哦~"
L18_1.m_Talk_DEU = "Sie werden es bereuen, wenn Sie das Video nicht bis zum Ende schauen! Und vergessen Sie nicht, das Video nach dem Anschauen zu liken und den Kanal zu abonnieren."
L18_1.m_Talk_FRA = "Restez jusqu'à la fin de la vidéo pour une surprise que vous ne regretterez pas ! Et bien sûr, n'oubliez pas de vous abonner pour ne pas manquer nos prochaines vidéos !"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 4100301
L19_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Talk_KOREA = "루이제 슈나이더, 사진으로 보시다시피 처음 데뷔할 때부터 그 미모로 호평을 받았는데요."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "ルイーゼ・シュナイダー、写真でおわかりのように、デビューした時からその美しさで話題となりました。"
L19_1.m_Talk_ENG = "Louise Schneider, as you can see from this picture, has been well known for her beauty ever since she debuted."
L19_1.m_Talk_TWN = "露易絲·修奈德，從照片上可以看到，從她出道開始，就因她的美貌而受到大家喜愛。"
L19_1.m_Talk_THA = "ลูอิส ไชนเดอร์ อย่างที่คุณเห็นในภาพ มีความงดงามเป็นที่เลื่องลือตั้งแต่ตอนเดบิวต์"
L19_1.m_Talk_VTN = "Louise Schneider, như bạn có thể thấy trong bức ảnh này, đã nổi tiếng với vẻ đẹp của mình kể từ khi ra mắt."
L19_1.m_Talk_SCN = "……路易丝·施耐德，正如我们现在看到的这张照片一样，她出道时就因其光彩照人的美貌而广受好评。"
L19_1.m_Talk_DEU = "Louise Schneider, wie Sie auf diesem Bild sehen können, ist seit ihrem Debüt für ihre außerordentliche Schönheit bekannt."
L19_1.m_Talk_FRA = "Comme en témoigne cette photo époque, Louise Schneider a toujours brillé par son indicible beauté et ce, dès ses débuts."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 4100301
L20_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Talk_KOREA = "저희 넷튜브 채널을 통해 접촉해 온 제보자에 따르면, 반군들에게 딸과 자신의 안전을 대가로 몸을……"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "我らのネットチューブチャンネルを通じて接触してきた情報提供者によりますと、娘と自分の身の安全の見返りに反乱軍に身を……"
L20_1.m_Talk_ENG = "And according to an informant connected with our NetTube channel, in exchange for her and her daughter’s safety, she was forced to sell her body..."
L20_1.m_Talk_TWN = "但是我們收到內幕消息，據說她以自己和女兒的安全為代價，獻身給叛軍……"
L20_1.m_Talk_THA = "และจากผู้ให้ข้อมูลที่ติดต่อกับช่อง NetTube ของเรา เพื่อแลกกับความปลอดภัยของตัวเองและลูกสาว เธอถูกบังคับให้ขายร่างของเธอ..."
L20_1.m_Talk_VTN = "Và theo một nguồn tin kết nối với kênh NetTube của chúng tôi, để đổi lấy sự an toàn của bản thân và con gái, cô ấy buộc phải bán mình..."
L20_1.m_Talk_SCN = "根据一位与我们NetTube频道有关系的线人透露，她为了女儿和自身的安全，被迫与叛军们……"
L20_1.m_Talk_DEU = "Und laut einem Informanten, der mit uns über den NetTube-Kanal in Kontakt steht, war sie gezwungen, ihren Körper an die Rebellen zu verkaufen, um ihre eigene sowie die Sicherheit ihrer Tochter zu gewährleisten ..."
L20_1.m_Talk_FRA = "D'après un informateur qui travaille en partenariat avec notre chaîne NetTube, elle aurait ainsi été forcée de vendre son propre corps en échange de sa sécurité et de celle de sa fille..."
