L25_1 = {}
L25_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@25#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 4100301
L25_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_StartBGMFileName = "CUTSCENE_TALK_06"
L25_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L25_1.m_bCharHologramEffect = true
L25_1.m_Talk_KOREA = "……그래서 확보한 건 결국 그 악보뿐이라는 건가?"
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "……それで、確保したのは結局その楽譜だけなのか？"
L25_1.m_Talk_ENG = "...Anyways, is the musical score the only thing you secured?"
L25_1.m_Talk_TWN = "……所以你們只有找到那個樂譜嗎？"
L25_1.m_Talk_THA = "...สรุปคือ เธอเอามาได้แค่โน้ตเพลงใช่มั้ย?"
L25_1.m_Talk_VTN = "...Dù sao đi nữa, bản nhạc là thứ duy nhất cô lấy được?"
L25_1.m_Talk_SCN = "……所以，你们只拿到了那个乐谱？"
L25_1.m_Talk_DEU = "... Also, sind die Noten das einzige, was ihr sichern konntet?"
L25_1.m_Talk_FRA = "... Donc tout ce que tu as trouvé, c'est cette partition ?"
L26_1 = {}
L26_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@26#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 4100301
L26_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_DESPAIR"
L26_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "네, 침식체는 사살 직후 신체가 붕괴하더군요."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "はい。侵食体は射殺直後に体が崩壊しました。"
L26_1.m_Talk_ENG = "That’s correct. The Corrupted Object collapsed immediately after being shot."
L26_1.m_Talk_TWN = "對，射殺侵蝕體後，它的身體就開始解體。"
L26_1.m_Talk_THA = "ค่ะ หลังถูกยิง วัตถุคอร์รัปต์ก็ตายทันที"
L26_1.m_Talk_VTN = "Đúng vậy. Vật Thể Ăn Mòn đã sụp đổ ngay lập tức sau khi bị bắn."
L26_1.m_Talk_SCN = "是的。侵蚀体被杀后身体就直接崩溃了。"
L26_1.m_Talk_DEU = "So ist es. Das Counterside-Objekt brach sofort nach dem Schuss zusammen."
L26_1.m_Talk_FRA = "Oui. Malheureusement, l'O.C. s'est désintégré aussitôt que nous l'avons vaincu."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@27#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 4100301
L27_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "인간의 생체 조직 일부가 남은 걸로 봐선, 변이가 급격하게 진행된 모양이에요."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "人間の生体組織が一部残ってるところを見ると、急激に変異したようです。"
L27_1.m_Talk_ENG = "Given that some of the human biological tissue remains, the mutation seems to have occurred only recently."
L27_1.m_Talk_TWN = "從它還留有部分人體組織來看，應該是在很緊急的情況下變異的。"
L27_1.m_Talk_THA = "ดูจากเนื้อเยื่อจากร่างกายมนุษย์ที่เหลืออยู่แล้วคงเพิ่งกลายพันธุ์ได้ไม่นาน"
L27_1.m_Talk_VTN = "Do một số mô sinh học của con người vẫn còn, sự đột biến dường như chỉ xảy ra gần đây."
L27_1.m_Talk_SCN = "根据其仍旧留有一部分人类身体组织的这一情况，我推测可能是出现了急速变异。"
L27_1.m_Talk_DEU = "Nach den Überresten des menschlichen biologischen Gewebes zu urteilen, scheint die Mutation schnell fortgeschritten zu sein."
L27_1.m_Talk_FRA = "En revanche, il possédait encore des fragments de tissu biologique humain, ce qui suggère que sa mutation a eu lieu récemment."
L28_1 = {}
