L29_1 = {}
L29_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 4100301
L29_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_StartFXSoundName = "FX_CUTSCEN_PHONE"
L29_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L29_1.m_Talk_KOREA = "침식 증후군으로 인한 말로라기에는 석연치 않군."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "侵食症候群による末路にしては釈然としないな。"
L29_1.m_Talk_ENG = "But we can’t be sure due to the Corruption Syndrome."
L29_1.m_Talk_TWN = "但這也無法解釋是因為侵蝕症候群而造成的。"
L29_1.m_Talk_THA = "แต่กลุ่มอาการคอร์รัปชั่นก็ทำให้ชี้ชัดไม่ได้"
L29_1.m_Talk_VTN = "Nhưng chúng tôi không thể chắc chắn đó là do Hội Chứng Ăn Mòn."
L29_1.m_Talk_SCN = "但我总感觉就这样定义为侵蚀症候群，有些不妥当。"
L29_1.m_Talk_DEU = "Aufgrund des Verderbnissyndroms können wir uns jedoch nicht sicher sein."
L29_1.m_Talk_FRA = "Mais avec le Syndrome de Corruption, impossible de savoir quand exactement."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 4100301
L30_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L30_1.m_Talk_KOREA = "그 침식지대의 CSE 레벨은 2를 넘지 않아. 그런데도 그 며칠 사이 2종 침식체가 되었다면……"
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "あの侵食地帯のCSEレベルは2に満たない。なのに、この何日間で第2種侵食体になったのなら……"
L30_1.m_Talk_ENG = "That Corrupted Area’s CSE level has never exceeded level 2. And yet, just a few days ago, a Category 2 Corrupted Object..."
L30_1.m_Talk_TWN = "那個侵蝕地帶的CSE等級不到2，要在這短的時間內變成2類侵蝕體……"
L30_1.m_Talk_THA = "ระดับ CSE ของบริเวณที่ถูกคอร์รัปต์แห่งนั้นไม่เคยเกินระดับ 2 แต่ถึงอย่างนั้น แค่ไม่กี่วันที่ผ่านมา ก็มีวัตถุคอร์รัปต์คลาส 2..."
L30_1.m_Talk_VTN = "Cấp CSE của Khu Vực Bị Ăn Mòn đó chưa bao giờ vượt quá cấp độ 2. Tuy nhiên, chỉ vài ngày trước, một Vật Thể Ăn Mòn cấp 2..."
L30_1.m_Talk_SCN = "那个侵蚀地区的CSE等级从来没有超过2级。但他在几天时间内就变异成了2级侵蚀体……"
L30_1.m_Talk_DEU = "Die CSE-Stufe dieses Verderbten Gebietes hat noch nie Level 2 überschritten und dennoch wurde es vor wenigen Tagen zu einem C. O.s der Kategorie 2 ..."
L30_1.m_Talk_FRA = "Le niveau d'ECM de cette Zone Corrompue n'a jamais dépassé 2. Alors comment expliquer la présence d'un O.C. de catégorie 2... ?"
L31_1 = {}
L31_1.m_CutScenKey_Talk = "GRONIA_ACT3_INTERLUDE1@31#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 4100301
L31_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_IDLE"
L31_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L31_1.m_Pos = "C"
L31_1.m_Talk_KOREA = "다른 고준위 침식파에 노출되었거나, 누군가가 인위적으로 저지른 짓이겠죠."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "他の高レベルの侵食波にさらされたか、あるいは誰かが人為的に変異させたのでしょう。"
L31_1.m_Talk_ENG = "It must be due to exposure to other high-level Corruption rays, or someone is artificially creating it."
L31_1.m_Talk_TWN = "除非是暴露在高侵蝕波中，或是人為造成的。"
L31_1.m_Talk_THA = "อาจเพราะการสัมผัสกับรังสีคอร์รัปชั่นในระดับสูงค่ะ หรือไม่ก็มีอะไรทำเทียมมันขึ้นมา"
L31_1.m_Talk_VTN = "Phải là do tiếp xúc với các Tia Ăn Mòn cấp cao khác, hoặc ai đó đang tạo ra nó."
L31_1.m_Talk_SCN = "不是受到更高危险级侵蚀波的影响，就是有人为的干涉。"
L31_1.m_Talk_DEU = "Es muss einer anderen hochgradigen Verderbniswelle ausgesetzt gewesen sein, oder jemand hat es auf künstliche Weise verursacht."
L32_1 = "Le spécimen avait peut être été surexposé à des Rayons de Corruption de haute intensité ou reproduits artificiellement..."
L31_1.m_Talk_FRA = L32_1
