L35_1 = "GRONIA_ACT3_INTERLUDE1@34#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 34
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4100301
L34_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "UNIT_SERIOUS"
L34_1.m_Face = L35_1
L34_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L35_1 = "R"
L34_1.m_Pos = L35_1
L35_1 = "강경파 반군과 협력하던 제프티 바이오테크에서 침식체를 병기로 활용하려는 움직임이 있었습니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "強硬派の反乱軍と協力していたジェフティ・バイオテックで、侵食体を兵器に使おうとする動きがありました。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "There was a movement to use Corrupted Objects as a weapon at Jehuty Biotech, which was cooperating with rebels from the hardliners."
L34_1.m_Talk_ENG = L35_1
L35_1 = "之前和強硬派叛軍合作過的傑夫堤生物科技，就曾經將侵蝕體作為武器使用。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ที่เจฮูตีไบโอเทคมีความพยายามจะใช้วัตถุคอร์รัปต์เป็นอาวุธอยู่ พวกนั้นร่วมมือกับพวกกบฏจากฮาร์ดไลเนอร์"
L34_1.m_Talk_THA = L35_1
L35_1 = "Có một phong trào sử dụng Vật Thể Ăn Mòn làm vũ khí tại Jehuty Biotech, công ty đang hợp tác với phiến quân từ phái cứng rắn."
L34_1.m_Talk_VTN = L35_1
L35_1 = "根据报告，与强硬派叛军有合作关系的杰普提生物科技曾经有过将侵蚀体当做兵器使用的情况。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Bei Jehuty Biotech gab es eine Bewegung, die versucht hat, Counterside-Objekte als Waffen einzusetzen. Diese Bewegung hat mit den extremistischen Rebellen zusammengearbeitet."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ce pourrait être le travail de Jehuty Biotech, cette organisation qui essaie d'utiliser les O.C. pour en faire des armes et qui a déjà coopéré avec les Insoumis par le passé."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "GRONIA_ACT3_INTERLUDE1@35#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4100301
L35_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L36_1 = "R"
L35_1.m_Pos = L36_1
L36_1 = "그 연장선상이라고 하면 퍼즐이 맞아 떨어져요. 클림트의 정체를 비롯해 더 적극적인 조사가 필요합니다."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "その延長なのだと考えれば理にかないます。クリムトの正体を始めとしてもっと積極的に調査する必要があります。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "The pieces of the puzzle all fit. Still, further investigation is needed, including into Klimt's real identity."
L35_1.m_Talk_ENG = L36_1
L36_1 = "這樣事件的拼圖就可以拼湊起來。從克里姆的真實身分開始，需要更積極地展開調查。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ปริศนาทั้งหมดไขกระจ่างแล้ว แต่ก็ยังต้องตรวจสอบเพิ่มเติมอยู่นะคะ โดยเฉพาะเรื่องตัวตนที่แท้จริงของคลิมต์"
L35_1.m_Talk_THA = L36_1
L36_1 = "Các mảnh ghép đều vừa vặn. Tuy nhiên, vẫn cần điều tra thêm, bao gồm cả danh tính thực sự của Klimt."
L35_1.m_Talk_VTN = L36_1
L36_1 = "如果将这些线索串联起来，那么拼图就完整了。我觉得对克里姆特的真实身份，需要进行更详尽的调查。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wenn es eine Erweiterung davon ist, dann fügen sich langsam, aber sich alle Teile des Puzzles zusammen. Eine aktivere Untersuchung ist erforderlich, einschließlich der wahren Identität von Klimt."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Les pièces du puzzle s'emboîtent parfaitement. Une enquête approfondie est nécessaire, nous devons découvrir ce que cache Klimt."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
