L38_1 = "GRONIA_ACT3_INTERLUDE1@37#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4100301
L37_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L38_1 = "L"
L37_1.m_Pos = L38_1
L38_1 = "일리는 있지만 당장은 건국절 행사가 우선이야. 호들갑을 떨면서 대처할 필요까지는 없어."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "一理あるが、今は建国記念日が先だ。大げさに対処するまでの必要はない。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "It may make sense, nevertheless, the National Foundation Day event takes priority. You don’t have to worry about that right now."
L37_1.m_Talk_ENG = L38_1
L38_1 = "話是有道理，但現在當務之急是先把國慶典禮辦好，不需要大動作處理。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "มันอาจสมเหตุสมผลจริง แต่ถึงอย่างนั้น วันสถาปนาแห่งชาติต้องมาก่อน เธอยังไม่ต้องกังวลเรื่องนั้นตอนนี้หรอก"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tuy nhiên, nó có thể hợp lý, sự kiện Ngày Thành Lập Quốc Gia được ưu tiên. Cô không phải lo lắng về điều đó ngay bây giờ."
L37_1.m_Talk_VTN = L38_1
L38_1 = "虽然你说的很有道理，但现在首要的是建国节活动。没必要将精力浪费到其他地方。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das macht zwar Sinn, aber im Moment steht der Nationale Gründungstag an erster Stelle. Du musst dir darum momentan keine Sorgen machen."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ton raisonnement se tient, mais le concert commémoratif reste notre priorité absolue. Tiens-toi à carreau pour le moment."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "GRONIA_ACT3_INTERLUDE1@38#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 38
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4100301
L38_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L39_1 = "R"
L38_1.m_Pos = L39_1
L39_1 = "m_Crash"
L38_1[L39_1] = 15
L39_1 = "국장님. 전황에 악영향을 끼칠 수도 있어요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "局長。戦況に悪い影響が出るかもしれません。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Chief, it could negatively impact our current situation."
L38_1.m_Talk_ENG = L39_1
L39_1 = "部長，這樣恐怕會對局勢有不好的影響！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "หัวหน้าคะ มันอาจส่งผลเสียต่อสถานการณ์ปัจจุบันของเรานะคะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Cục Trưởng, điều này có thể tác động tiêu cực đến tình hình hiện tại của chúng ta."
L38_1.m_Talk_VTN = L39_1
L39_1 = "局长。这可能会对当前形势产生不利影响。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Chef, es könnte sich negativ auf unsere aktuelle Situation auswirken."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais, chef ! Les deux évènements sont sans doute liés !"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "GRONIA_ACT3_INTERLUDE1@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 4100301
L39_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L40_1 = "L"
L39_1.m_Pos = L40_1
L40_1 = "레버넌트……. 자네에게 해외 임무를 주로 맡겼던 건 그 충동적인 면 때문이야."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "レヴナント……君に主に海外の任務を任せたのは、その衝動的な一面のせいだ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Revenant... It’s because of this instinctual side of yours that I’ve entrusted you mainly with overseas missions."
L39_1.m_Talk_ENG = L40_1
L40_1 = "亡靈……我之所以都讓你負責海外的任務，就是因為你太容易衝動。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เรเวแนนต์... เพราะสัญชาติญาณแบบนี้แหละ ผมเลยวางใจให้เธอไปทำภารกิจเมืองนอกหลายชิ้น"
L39_1.m_Talk_THA = L40_1
L40_1 = "Revenant... Chính vì khía cạnh bản năng này của cô mà tôi đã tin tưởng giao cho cô chủ yếu là nhiệm vụ ở nước ngoài."
L39_1.m_Talk_VTN = L40_1
L40_1 = "亡灵……我之所以让你主要负责海外任务，也是考虑到你冲动的性格。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Revenant ... Wegen dieser impulsiven Seite habe ich dir hauptsächlich Missionen im Ausland anvertraut."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Revenant... Tu as conscience que c'est ton côté impulsif qui te vaut généralement d'être assignée pour des missions à l'étranger, n'est-ce pas ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "GRONIA_ACT3_INTERLUDE1@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4100301
L40_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L41_1 = "L"
L40_1.m_Pos = L41_1
L41_1 = "반군과 엮일 구석이 보이면 이상하리만큼 냉정함을 유지하지 못해."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "反乱軍と絡む余地があると、おかしいくらいに冷静さを失う。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "For whatever the reason, you can’t seem to maintain your composure when it comes to the rebels."
L40_1.m_Talk_ENG = L41_1
L41_1 = "事情只要牽扯到叛軍，你就會失去理性。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "แต่จะด้วยเหตุผลอะไรก็เถอะ พอเป็นเรื่องพวกกบฏแล้วเธอดูจะเสียความเยือกเย็นไปนะ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Vì lý do gì đó, cô dường như không thể giữ được bình tĩnh khi nói đến phiến quân."
L40_1.m_Talk_VTN = L41_1
L41_1 = "每次与叛军有关时，你总是一反常态地无法冷静。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Aus irgendeinem Grund hast du dich einfach nicht unter Kontrolle, sobald es um die Rebellen geht."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Tu es incapable de garder ton sang-froid face aux rebelles, c'est un fait."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
