L43_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L43_1.m_Pos = "C"
L43_1.m_bCharHologramEffect = true
L44_1 = "악보는 자네가 직접 보안국으로 가져오도록 해."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "楽譜は君が直接保安局に持ってくるように。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I want you to submit the full score to the National Security in person."
L43_1.m_Talk_ENG = L44_1
L44_1 = "樂譜你就直接拿到安全局來，"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ผมอยากให้เธอส่งโน้ตเพลงทั้งฉบับให้สำนักงานความมั่นคงแห่งชาติโดยตรง"
L43_1.m_Talk_THA = L44_1
L44_1 = "Tôi muốn cô trực tiếp nộp toàn bộ bản nhạc cho Cục An Ninh Quốc Gia."
L43_1.m_Talk_VTN = L44_1
L44_1 = "乐谱需要你亲自带到安全局来。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Ich möchte, dass du die Noten persönlich bei der Abteilung für nationale Sicherheit einreichst."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Pour le moment, je te charge de remettre la partition au Bureau."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GRONIA_ACT3_INTERLUDE1@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4100301
L44_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "파레마 건에 대해서도 자네와 단둘이 할 얘기가 있으니까."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "パレマの件についても君と二人きりで話したいからな。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Furthermore, I need to have a conversation with you about the Parema operation."
L44_1.m_Talk_ENG = L45_1
L45_1 = "波雷馬的事我也有話要跟你說。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แล้วก็ เราสองคนต้องคุยกันเรื่องปฏิบัติการพาเรมา"
L44_1.m_Talk_THA = L45_1
L45_1 = "Hơn nữa, hai chúng ta cần nói chuyện về Tác chiến Parema."
L44_1.m_Talk_VTN = L45_1
L45_1 = "有关巴乐马的事情，我也需要和你单独谈谈。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Darüber hinaus muss ich mit dir etwas in Bezug auf die Parema-Mission besprechen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Et n'oublie pas, je dois toujours avoir un mot avec toi concernant l'opération Parema..."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "GRONIA_ACT3_INTERLUDE1@45#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 45
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4100301
L45_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "오늘은 우선 휴식을 취하게. 나는 이 사안을 어떻게 처리할지 관련자들과 논의해야겠어."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "今日はまず休め。私はこの案件をどう処理するか、関係者と議論してみよう。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "For now, call it a day. I need to discuss how to handle this with those related to the matter."
L45_1.m_Talk_ENG = L46_1
L46_1 = "你今天就先休息吧，至於這件事要如何處理，等我跟相關人士討論過後再說。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ตอนนี้ก็แค่นี้ก่อนแล้วกัน ผมต้องไปหาวิธีรับมือกับเรื่องอื่นๆ ที่เกี่ยวข้อง"
L45_1.m_Talk_THA = L46_1
L46_1 = "Còn bây giờ, xong việc rồi. Tôi cần thảo luận về cách xử lý việc này với những người có liên quan đến vấn đề này."
L45_1.m_Talk_VTN = L46_1
L46_1 = "今天你就先休息吧。我会与有关人员讨论如何处理这次事件。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Das war es erstmal für heute. Ich muss mit den an dieser Sache beteiligten Personen sprechen, wie ich mit dieser Angelegenheit umgehen soll."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Pour le moment, reste à l'ombre. Je dois discuter d'un plan d'attaque avec mes supérieurs."
L45_1.m_Talk_FRA = L46_1
