L48_1.m_Face = "UNIT_DESPAIR"
L48_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L49_1 = "R"
L48_1.m_Pos = L49_1
L49_1 = "……잠시만요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……待ってください。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "...Wait."
L48_1.m_Talk_ENG = L49_1
L49_1 = "……先等一下。"
