L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L51_1 = "R"
L50_1.m_Pos = L51_1
L51_1 = "이 악보에 적힌 곡, 행사 당일의 세트리스트에는 오르지 않았어요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "この楽譜の曲、行事当日のセットリストには載ってなかったんです。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "The song of this score was not on the setlist on the day of the event."
L50_1.m_Talk_ENG = L51_1
L51_1 = "樂譜上寫的歌，並沒有出現在國慶日當天的曲目上。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เพลงในโน้ตนี้ไม่ได้อยู่ในรายชื่อการแสดงของวันงานนะคะ"
L50_1.m_Talk_THA = L51_1
L51_1 = "Bài hát của bản nhạc này không có trong danh sách vào ngày diễn ra sự kiện."
L50_1.m_Talk_VTN = L51_1
L51_1 = "这个乐谱上的曲目，不在活动当天的歌单中。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Das mit diesen Noten geschriebene Lied, stand am Tag der Aufführung nicht auf der Setlist."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Le morceau sur la partition ne figure pas dans le répertoire du concert de cette année."
L50_1.m_Talk_FRA = L51_1
