L2_1 = "R"
L1_1.m_Pos = L2_1
L2_1 = "그리고…… 제 기억이 맞다면……"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そして……私の記憶に間違いがなければ……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "And... If I remember correctly..."
L1_1.m_Talk_ENG = L2_1
L2_1 = "而且……若我沒記錯……"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แล้วก็... ถ้าฉันจำไม่ผิดละก็..."
L1_1.m_Talk_THA = L2_1
L2_1 = "Và... Nếu tôi nhớ không lầm..."
L1_1.m_Talk_VTN = L2_1
L2_1 = "还有……如果我没记错……"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Und ... wenn ich mich richtig erinnere ..."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Et si je me souviens bien..."
