L2_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L3_1 = "L"
L2_1.m_Pos = L3_1
L3_1 = "예상대로라네."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "君の予想どおりだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "That’s to be expected."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你猜得沒錯。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ก็ไม่แปลกนะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Điều đó đã được dự tính trước."
L2_1.m_Talk_VTN = L3_1
L3_1 = "在我意料之中。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das ist zu erwarten."
L2_1.m_Talk_DEU = L3_1
L3_1 = "C'est à prévoir."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "GRONIA_ACT3_INTERLUDE1@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4100301
L3_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "그건 자네 어머니가 준비하던 미발표 곡이야. 당일 공연 때 공개될 예정이었지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "それは君の母親が準備していた未発表の曲だ。当日の公演で公開されるはずだった。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "It’s an unreleased piece that your mother was working on. It was set to be revealed at the day of the concert."
L3_1.m_Talk_ENG = L4_1
L4_1 = "那是你媽媽未發表的曲目，原本是預計在表演當天發表的。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "มันเป็นผลงานที่ไม่ได้เผยแพร่ของแม่เธอ มีกำหนดให้เปิดตัวในวันที่มีคอนเสิร์ต"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đó là một tác phẩm chưa được phát hành mà mẹ của cô đang sáng tác. Nó dự kiến được tiết lộ vào buổi hòa nhạc."
L3_1.m_Talk_VTN = L4_1
L4_1 = "这是你母亲未公开的曲目。本来是会在演出当天发表的。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Es ist ein unveröffentlichtes Musikstück, an dem deine Mutter gearbeitet hat. Es sollte am Tag der Aufführung zum ersten Mal gespielt werden."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Ce morceau, c'est une nouvelle composition sur laquelle travaillait ta mère. Elle aurait dû être révélée le jour du concert."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "GRONIA_ACT3_INTERLUDE1@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 4100301
L4_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "UNIT_SURPRISE"
L4_1.m_Face = L5_1
L4_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "그럼 클림트가 저희 집에 방문했던 것도, 설마 악보 때문이란 말인가요?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "それじゃあクリムトが私の家に訪れたのも、まさか楽譜のせいなんですか？"
L4_1.m_Talk_JPN = L5_1
L5_1 = "So Klimt visited my house because of that piece?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "難道克里姆會找到我家來，就是因為這個樂譜嗎？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "งั้นคลิมต์ก็ไปบ้านฉันเพราะเพลงนี้เหรอคะ?"
L4_1.m_Talk_THA = L5_1
L5_1 = "Vậy Klimt đến thăm nhà tôi vì mảnh giấy đó à?"
L4_1.m_Talk_VTN = L5_1
L5_1 = "那么克里姆特去我家，也是因为这个乐谱？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Also hat Klimt etwa mein Haus wegen dieses Musikstücks besucht?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Alors c'est pour ça que Klimt est venu chez moi ? Pour la voir ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "GRONIA_ACT3_INTERLUDE1@55#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 55
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 4100301
L5_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L6_1 = "L"
L5_1.m_Pos = L6_1
L6_1 = "그럴 가능성도 배제할 수 없지."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "その可能性も無視できない。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "We can’t rule out the possibility."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不排除有這個可能。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เรื่องนั้นก็อาจเป็นไปได้เหมือนกัน"
L5_1.m_Talk_THA = L6_1
L6_1 = "Không thể loại trừ khả năng này."
L5_1.m_Talk_VTN = L6_1
L6_1 = "不能排除这个可能性。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Diese Möglichkeit kann nicht ausgeschlossen werden."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Nous ne pouvons pas exclure cette possibilité."
L5_1.m_Talk_FRA = L6_1
