L8_1 = "GRONIA_ACT3_INTERLUDE1@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4100301
L7_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_bCharHologramEffect = true
L8_1 = "알다시피, 그건 자네 어머니가 반군의 사보타주에 휘말리고 나서 준비하던 곡이야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "知っていると思うが、それは君の母親が反乱軍のサボタージュに巻き込まれた後に準備していた曲だ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "As you know, it’s the piece your mother was in the middle of working on after the terrorist attack occurred."
L7_1.m_Talk_ENG = L8_1
L8_1 = "你也知道，那是你媽媽在捲入叛軍恐怖事件後才寫的曲子。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "อย่างที่เธอก็รู้ มันเป็นเพลงที่แม่เธอแต่งค้างไว้ตอนที่พวกผู้ก่อการร้ายโจมตี"
L7_1.m_Talk_THA = L8_1
L8_1 = "Như cô đã biết, đó là thứ mà mẹ cô đang sáng tác dở sau khi vụ tấn công khủng bố xảy ra."
L7_1.m_Talk_VTN = L8_1
L8_1 = "正如你所知，这是你母亲被卷入叛军蓄意破坏事件时还在创作的曲目。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Wie du bereits weißt, ist es das Musikstück, an dem deine Mutter nach dem Terroranschlag gearbeitet hat."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Tu sais sans doute que ta mère travaille sur cette pièce depuis l'attaque terroriste, n'est-ce pas ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "GRONIA_ACT3_INTERLUDE1@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 4100301
L8_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "정신질환에 시달리던 데다가 내전으로 인해 잊혀 버렸지만……."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "精神病を病んでいた上に、内戦のせいで忘れられたが……"
L8_1.m_Talk_JPN = L9_1
L9_1 = "It may have been largely forgotten because of her mental illness and because of the civil war, but even so..."
L8_1.m_Talk_ENG = L9_1
L9_1 = "雖然你媽媽受精神疾病所苦，又因為內戰而被遺忘……"
L8_1.m_Talk_TWN = L9_1
L9_1 = "มันอาจถูกลืมไปเยอะเพราะความป่วยไข้ทางจิตใจของเธอแล้วก็สงครามกลางเมือง แต่ถึงอย่างนั้น..."
L8_1.m_Talk_THA = L9_1
L9_1 = "Nó có thể đã bị lãng quên phần lớn vì bệnh tâm thần của bà ấy và vì cuộc nội chiến, nhưng ngay cả như vậy..."
L8_1.m_Talk_VTN = L9_1
L9_1 = "虽然因为你母亲的精神问题还有内战，导致这个曲目被人遗忘了……"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Es mag aufgrund ihrer psychischen Erkrankung und wegen des Bürgerkriegs weitgehend vergessen worden sein, aber trotzdem ..."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Entre la guerre civile et ses crises d'amnésie ce morceau a fini par tomber dans l'oubli, mais..."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "GRONIA_ACT3_INTERLUDE1@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4100301
L9_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "곡의 주제는 화해와 평화라더군."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "曲の主題は和解と平和だそうだな。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "The theme of the piece was reconciliation and peace."
L9_1.m_Talk_ENG = L10_1
L10_1 = "但曲子的主題是關於和平。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ธีมของเพลงคือความสมานผมท์และสันติภาพ"
L9_1.m_Talk_THA = L10_1
L10_1 = "Chủ đề của tác phẩm là hòa giải và hòa bình."
L9_1.m_Talk_VTN = L10_1
L10_1 = "但我听说这个曲目的主题是理解与和平。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Das Thema des Musikstücks war Versöhnung und Frieden."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Il avait pour thème initial la réconciliation et la paix."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "GRONIA_ACT3_INTERLUDE1@60#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 60
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 4100301
L10_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_DESPAIR"
L10_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "그래요. 한동안은 정신이 온전하셨으니까요."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そうです。しばらくは正気でしたので。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Yes. Her mind was able to stay healthy for a while."
L10_1.m_Talk_ENG = L11_1
L11_1 = "我知道，我媽有一陣子精神狀況很穩定。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ค่ะ ตอนนั้นจิตใจแม่ยังพอปกติดีอยู่"
L10_1.m_Talk_THA = L11_1
L11_1 = "Đúng. Tâm trí bà ấy đã có thể khỏe mạnh trong một thời gian."
L10_1.m_Talk_VTN = L11_1
L11_1 = "不……妈妈至少有一段时间精神是正常的。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ja. Ihr Verstand war für eine Weile klar."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je sais, oui. À l'époque, elle avait encore toute sa tête."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "GRONIA_ACT3_INTERLUDE1@61#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 61
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 4100301
L11_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L11_1.m_Pos = "C"
L12_1 = "그 이상한 소문들만 퍼지지 않았더라도……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あの変な噂さえなかったら……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "If only those rumors didn’t spread..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "要不是因為那個奇怪的傳言……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ถ้าเพียงแต่ข่าวลือนั่นไม่กระจายไป..."
L11_1.m_Talk_THA = L12_1
L12_1 = "Giá như những tin đồn đó không lan rộng..."
L11_1.m_Talk_VTN = L12_1
L12_1 = "如果没有那些奇怪传闻的话……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wenn sich nur diese Gerüchte nicht verbreitet hätten ..."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Si seulement cette maudite rumeur ne s'était jamais propagée..."
L11_1.m_Talk_FRA = L12_1
