L15_1 = "GRONIA_ACT3_INTERLUDE1@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 4100301
L14_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L15_1 = "L"
L14_1.m_Pos = L15_1
L14_1.m_bCharHologramEffect = true
L15_1 = "너무 애석해하지 말게. 자네 어머니를 안타깝게 여긴 여론 덕분에 반정부 단체를 억제할 수 있었어."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そう悲しむな。君の母親を気の毒と考えたマスコミのおかげで反政府団体を抑えられたんだ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Don’t beat yourself up too much about that. Thanks to that, we were able to use the resulting public outrage about what happened to your mother and suppress the anti-government organization."
L14_1.m_Talk_ENG = L15_1
L15_1 = "你也別太糾結於此，幸虧輿論是站在你媽媽那邊，才能打壓反政府團體。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "อย่าโทษตัวเองให้มากไปเลย เพราะมีเรื่องนั้นเราเลยได้ใช้ประโยชน์จากความโกรธแค้นที่ผู้คนมีต่อเรื่องที่เกิดกับแม่เธอ แล้วก็ปราบปรามพวกองค์กรต่อต้านรัฐบาลได้"
L14_1.m_Talk_THA = L15_1
L15_1 = "Đừng đổ lỗi cho bản thân quá nhiều về chuyện đó. Nhờ đó, chúng tôi có thể sử dụng kết quả là sự phẫn nộ của công chúng về những gì đã xảy ra với mẹ cô và trấn áp tổ chức chống chính phủ."
L14_1.m_Talk_VTN = L15_1
L15_1 = "别再责备自己了……从好一点的地方想，也正是对你母亲表示同情的舆论，才能成功抑制反政府团体的气焰。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Sei nicht so betrübt deswegen. Dank ihnen konnten wir die daraus resultierende öffentliche Empörung dafür nutzen, um die extremistischen Regierungsgruppen zu unterdrücken."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ce n'est pas ta faute, arrête de t'en vouloir. Et puis cette histoire a fait réagir le peuple, c'est grâce à elle qu'on a pu mater la rébellion à l'époque."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "GRONIA_ACT3_INTERLUDE1@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4100301
L15_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L16_1 = "L"
L15_1.m_Pos = L16_1
L16_1 = "관리실패만 일어나지 않았다면……. 우리는 지금과 전혀 다른 나라에 살고 있었을 거야."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "管理失敗さえなければ……私たちは今とはまったく違う国に住んでいただろう。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "If it wasn’t for the Administration Failure...we would be living in a completely different country than we are now."
L15_1.m_Talk_ENG = L16_1
L16_1 = "要不是發生管理失敗……我們會生活在與現在完全不同的國家裡。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ถ้าไม่ใช่เพราะการล่มสลายขององค์การบริหารโลก... ประเทศที่เราอาศัยอยู่คงต่างจากตอนนี้คนละโลกเลย"
L15_1.m_Talk_THA = L16_1
L16_1 = "Nếu không phải vì sự cố Sai Sót Quản Trị... chúng ta đã có thể sống ở một đất nước hoàn toàn khác so với bây giờ."
L15_1.m_Talk_VTN = L16_1
L16_1 = "如果没有发生管理失败……我们的国家肯定与现在截然不同吧。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ohne das Verwaltungsversagen ... würden wir in einem ganz anderen Land leben als jetzt."
L15_1.m_Talk_DEU = L16_1
L16_1 = "La vraie tragédie, c'est la Chute de l'Administration. Si les choses s'étaient passées différemment, notre pays serait sans doute toujours en paix."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "GRONIA_ACT3_INTERLUDE1@66#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 66
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4100301
L16_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "UNIT_HATE"
L16_1.m_Face = L17_1
L16_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L17_1 = "R"
L16_1.m_Pos = L17_1
L17_1 = "말씀하시는 바는 이해합니다만, 그렇다고 그런 지저분한 소문을 퍼뜨린 자들을 용서하고 싶은 마음은 없습니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "お言葉はわかりますけど、それでもあんな汚い噂をバラまいた者たちを許す気はありません。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I understand what you’re saying, sir. But I still can’t forgive the ones who spread such horrible rumors."
L16_1.m_Talk_ENG = L17_1
L17_1 = "我明白你說的，但我還是無法原諒那些可惡的造謠者！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฉันเข้าใจที่คุณพูดนะคะ แต่ฉันก็ยังให้อภัยคนที่ปล่อยข่าวลือเลวทรามนั่นไม่ได้ค่ะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi hiểu những điều ông đang nói. Nhưng tôi vẫn không thể tha thứ cho những kẻ đã tung ra những tin đồn kinh khủng như vậy."
L16_1.m_Talk_VTN = L17_1
L17_1 = "……我能理解你说的意思，但即便这样，我也丝毫不想饶恕那些四处诽谤的家伙们。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich verstehe, was Sie sagen, Chef. Aber ich kann immer noch nicht denjenigen vergeben, die so schreckliche Gerüchte verbreitet haben."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Oui bien sûr. mais je ne pardonnerai jamais ceux qui sont à l'origine de ce mensonge."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "GRONIA_ACT3_INTERLUDE1@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4100301
L17_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L18_1 = "L"
L17_1.m_Pos = L18_1
L18_1 = "……그렇군."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "……そうか。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "I see..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "……好吧。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เช่นนี้เอง..."
L17_1.m_Talk_THA = L18_1
L18_1 = "Tôi hiểu..."
L17_1.m_Talk_VTN = L18_1
L18_1 = "……我明白了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Ich verstehe ..."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Je vois..."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "GRONIA_ACT3_INTERLUDE1@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4100301
L18_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "SIR_GRONIA_NULL_NULL"
L19_1 = "L"
L18_1.m_Pos = L19_1
L19_1 = "하긴, 지나간 일을 가지고 얘기할 필요는 없지. 이만 쉬게."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "まあ、終わったことであれこれ話す必要はないだろう。もう休め。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Maybe you're right, but what’s happened, happened. Get some rest."
L18_1.m_Talk_ENG = L19_1
L19_1 = "就先這樣吧，都已經是過去的事，也沒什麼好說的，去休息吧！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อาจจะถูกของเธอ แต่อะไรที่เกิดขึ้นแล้วก็ต้องเกิดไป ไปพักเถอะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Có thể cô đúng, nhưng điều gì đã xảy ra, thì cũng đã xảy ra. Chúng ta cần phải bước tiếp. Nghỉ ngơi chút đi."
L18_1.m_Talk_VTN = L19_1
L19_1 = "好吧，过去的事情再怎样也无法挽回。你还是好好休息吧。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Du magst vielleicht recht haben, aber die Vergangenheit kann man nicht ändern. Erhole dich jetzt etwas."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Enfin le passé, c'est le passé hein ? Allez, va te reposer."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
