L23_1 = "GRONIA_ACT3_INTERLUDE1@72#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4100301
L22_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "ROOKIE_GRONIA_NULL_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "상사랑 얘기는 잘 됐나요, 레버넌트 씨? 분위기가 심상치 않던데요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "上司との話はうまくいったんですか？　レヴナントさん。あんまりいいムードじゃなかったみたいですけど。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "How’d the talk go with your boss, Revenant? The atmosphere looked pretty tense."
L22_1.m_Talk_ENG = L23_1
L23_1 = "亡靈小姐，你和長官談得還好嗎？覺得氣氛有點怪怪的。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "คุณกับหัวหน้าเป็นไงบ้างล่ะเรเวแนนต์? บรรยากาศดูตึงเครียดมากเลย"
L22_1.m_Talk_THA = L23_1
L23_1 = "Cuộc nói chuyện với sếp của cô diễn ra như thế nào, Revenant? Bầu không khí trông khá căng thẳng."
L22_1.m_Talk_VTN = L23_1
L23_1 = "和上司谈得怎么样，亡灵？感觉气氛不是很好？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wie lief das Gespräch mit Ihrem Vorgesetzen, Revenant? Die Stimmung sah ziemlich angespannt aus."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Alors Revenant, ça c'est bien passé ? L'ambiance avait l'air plutôt tendue, là-bas."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "GRONIA_ACT3_INTERLUDE1@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4100301
L23_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "두 사람 앞에선 레아라고 불러."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "二人の前ではレアって呼んで。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Call me Leah in front of those two."
L23_1.m_Talk_ENG = L24_1
L24_1 = "在他們面前叫我蕾亞。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "เวลาอยู่กันสองคนก็เรียกฉันเลอาห์เถอะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Gọi tôi là Leah trước mặt hai người đó nhé."
L23_1.m_Talk_VTN = L24_1
L24_1 = "在她们两个人面前，请叫我蕾娅。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Nenn mich Leah vor diesen beiden."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Appelle-moi Leah devant ces deux-là, tu veux bien ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
