L27_1 = "GRONIA_ACT3_INTERLUDE1@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4100301
L26_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_LAUGH"
L26_1.m_Face = L27_1
L26_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L27_1 = "L"
L26_1.m_Pos = L27_1
L27_1 = "보통은 이런 편이야. 심각한 주제로 대화할 때가 대부분이니까."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "普段からこうなの。ほとんど深刻な案件で電話するから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "It’s always like that. We always talk about serious topics."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我們常這樣，因為每次講電話，幾乎都是談一些很嚴肅的事。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ก็แบบนั้นตลอดแหละ เราคุยแต่เรื่องเครียดๆ กันทุกที"
L26_1.m_Talk_THA = L27_1
L27_1 = "Luôn luôn như vậy. Chúng tôi luôn nói về những chủ đề nghiêm túc."
L26_1.m_Talk_VTN = L27_1
L27_1 = "其实也没怎么样。汇报的大部分时候，谈论的主题都比较沉重。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Das ist immer so. Wir sprechen immer über ernsthafte Themen."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Bah, c'est toujours pareil. Avec le chef, on peut pas se permettre un mot de travers."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "GRONIA_ACT3_INTERLUDE1@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4100301
L27_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ROOKIE_GRONIA_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "R"
L27_1.m_Pos = L28_1
L28_1 = "보안국 요원이라는 것도 참 피곤한 인생이네요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "保安局エージェントの人生って本当楽じゃないですね。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Being an agent of the National Security seems like a pretty rough life."
L27_1.m_Talk_ENG = L28_1
L28_1 = "安全局幹員的人生也是很不容易呢～"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ชีวิตการเป็นเจ้าหน้าที่ของสำนักงานความมั่นคงแห่งชาตินี่ดูยากเย็นอยู่นะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Trở thành một đặc vụ của Cục An Ninh Quốc Gia có vẻ như là một cuộc sống khá khó khăn."
L27_1.m_Talk_VTN = L28_1
L28_1 = "看来安全局特工的工作，也很疲惫啊。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Als eine Agentin der Abteilung für nationale Sicherheit, scheint man es wirklich nicht leicht zu haben."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Ça a pas l'air simple, la vie d'un agent du Bureau..."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "GRONIA_ACT3_INTERLUDE1@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4100301
L28_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L29_1 = "L"
L28_1.m_Pos = L29_1
L29_1 = "그러는 중사는 왜 집까지 따라왔어?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "そういう軍曹はなんで家までついてきたの？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "What about you, Sergeant? Why are you following me home?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "不過中士，你跟我回家幹嘛？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ว่าแต่ยังไงนะจ่า? ทำไมเธอตามฉันกลับมาบ้านด้วยเนี่ย?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Còn cô thì sao, Trung sĩ? Tại sao cô lại theo tôi về nhà?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "不过，中士，你一直跟我到家里干嘛？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Was ist mit dir, Unteroffizierin? Warum bist du mir bis nach Hause gefolgt?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Et on peut savoir pourquoi tu me suis jusqu'à chez moi ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "GRONIA_ACT3_INTERLUDE1@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 4100301
L29_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_DESPAIR"
L30_1 = "ROOKIE_GRONIA_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "R"
L29_1.m_Pos = L30_1
L30_1 = "설마 숙박비도 지원 안 해 줄 거라고는 예상 못했거든요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "まさか宿泊費も支援してくれないなんて予想もしなかったんで。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Well, I thought there’s no way I wouldn’t be provided any accommodations!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "因為我沒想到沒有住宿津貼。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แหม ก็ทีแรกฉันนึกว่ายังไงก็คงมีที่พักให้"
L29_1.m_Talk_THA = L30_1
L30_1 = "Chà, tôi tưởng không đời nào tôi không được cung cấp chỗ ở!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "呃……因为我没料到他们连住宿费都不给我提供。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich hatte nicht erwartet, dass man nicht einmal die Kosten für die Unterkunft übernehmen würde!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "C'est pourtant évident, non ? Attendez, je suis même pas logée pour la mission !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "GRONIA_ACT3_INTERLUDE1@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 4100301
L30_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "ROOKIE_GRONIA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "R"
L30_1.m_Pos = L31_1
L31_1 = "수도 방어 부대에 재워 달라고 연락했더니 무슨 헛소리냐는 핀잔이나 듣고."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "首都防御部隊に寝かしてくれって連絡したら、ふざけるなって叱られるし。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "But when I called the Capital Guard, asking for a place to stay, they just laughed at me, saying I couldn’t be serious!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "我有問首都防衛隊可不可以收留我一晚，結果被臭罵一頓，問我在胡說八道什麼。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แต่พอโทรขอที่พักจากฝ่ายพิทักษ์เมือง พวกนั้นก็หัวเราะใส่ให้ หาว่าฉันเพ้อเจ้อ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nhưng khi tôi gọi điện cho Cảnh vệ Thủ đô, hỏi chỗ ở, họ chỉ cười nhạo, nói tôi chắc đang không nghiêm túc!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "我给首都的防御部队打过电话，说是想找地方休息，结果却被骂回来了。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Aber als ich die städtische Wache anrief und um eine Unterkunft bat, lachten sie mich nur aus und sagten, ich könnte es nicht ernst meinen!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Et quand j'ai appelé les gardes de la capitale pour leur demander de m'héberger, ils se sont foutus de ma gueule."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "GRONIA_ACT3_INTERLUDE1@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4100301
L31_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_SURPRISE"
L31_1.m_Face = L32_1
L31_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L32_1 = "L"
L31_1.m_Pos = L32_1
L32_1 = "아무리 그래도 수훈자인데 하루치 숙박비가 없는 거야?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "いくらなんでも受勲者なのに一泊分の宿泊費もないの？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "What? You’re an awarded veteran with a medal and you have no money for accommodations?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "你好歹也是授勳者，身上連一天的住宿費都沒有嗎？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เอ้า? ทหารผ่านศึกฝีมือเป็นเลิศแถมได้เหรียญอย่างเธอไม่ได้เงินค่าที่พักเหรอ?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Cái gì? Cô là một cựu binh xuất sắc có huy chương và họ vẫn không cho cô tiền để ăn ở?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "可你作为授勋者，就没有额外的补贴吗？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Was? Du bist eine mit einem Orden ausgezeichnete Veteranin und hast dennoch kein Geld für eine Unterkunft?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tu vas me faire croire que tu n'as pas de quoi te payer un hôtel ? Toi, le héros national ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GRONIA_ACT3_INTERLUDE1@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4100301
L32_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "UNIT_HATE"
L32_1.m_Face = L33_1
L33_1 = "ROOKIE_GRONIA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "R"
L32_1.m_Pos = L33_1
L33_1 = "m_Crash"
L32_1[L33_1] = 15
L33_1 = "그건…… 으으음…… 뭐라고 해야 할지……."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "それは……ううん……何ていうか……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "That’s... Ummm... I don’t even know what to say."
L32_1.m_Talk_ENG = L33_1
L33_1 = "這個嘛……呃……該怎麼說呢……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "มันก็... เอิ่ม... หมดคำจะพูดเลยฉัน"
L32_1.m_Talk_THA = L33_1
L33_1 = "Đó là... Ummm... Tôi thậm chí không biết phải nói gì."
L32_1.m_Talk_VTN = L33_1
L33_1 = "那个……嗯……我也不知道该如何解释……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Das ist ... Ähm ... Ich weiß nicht, was ich sagen soll ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ah, ben... c'est parce qu'en fait..."
L32_1.m_Talk_FRA = L33_1
