L36_1 = "UNIT_HATE"
L35_1.m_Face = L36_1
L36_1 = "ROOKIE_GRONIA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "국경 넘으려고 브로커에게 있는 돈 다 갖다 줬다고 하면 가만 안 있겠지?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "国境を越えようと思ってブローカーにありったけのお金を渡したって言ったら、ただじゃ済まないよね？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "If I told her I gave all my money to smugglers to get me out of the country, she wouldn’t let me get away with it, right?"
L35_1.m_Talk_ENG = L36_1
L36_1 = "總不可能跟你說，我把錢都給了人蛇仲介吧？你知道還會放過我嗎？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ขืนบอกว่าฉันเอาเงินให้พวกขนคนออกนอกประเทศไปหมดแล้ว มีหวังเธอไม่ปล่อยฉันไปแน่ เนอะ?"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nếu nói với cô ấy rằng mình đã đưa tất cả tiền cho những kẻ buôn lậu để đưa mình ra khỏi đất nước, cô ấy sẽ không để mình thoát tội, đúng không nhỉ?"
L35_1.m_Talk_VTN = L36_1
L36_1 = "当然不能说是因为要偷渡，所以将全部积蓄都给了偷渡掮客吧？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Wenn ich ihr sagen würde, dass ich mein ganzes Geld Schmugglern gegeben habe, damit die mich aus dem Land bringen, würde sie mich nicht damit durchkommen lassen, oder?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Si je lui dis que j'ai filé toutes mes économies à un passeur qui doit me faire sortir du pays en douce, ça passe ou pas... ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
