L39_1 = "m_Crash"
L38_1[L39_1] = 20
L39_1 = "크헤헤, 이 앙증맞은 매국노 같으니. 보안국이 자랑하는 특별 심문 코스를 맛보여 주지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "クヘヘ、このかわいい売国奴め。保安局自慢の特別尋問コースを味わわせてあげるわ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Phaw, How dare you, you villainous traitor! Prepare yourself, for the National Security’s ultimate interrogation technique!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "哼哼哼，年紀輕輕的學人家做賣國賊！我就讓你嚐嚐安全局最引以為傲的問訊套餐吧！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "อ่าฮะ กล้าดีนักนะ ยัยคนทรยศ! เตรียมตัวพบกับเทคนิคการสอบปากคำขั้นสุดหลุดทุกคำสารภาพของสำนักงานความมั่นคงแห่งชาติให้ดีเถอะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Sao cô dám, đồ phản bội! Hãy chuẩn bị tinh thần cho màn thẩm vấn tối thượng của Cục An Ninh Quốc Gia!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "耶哈哈哈，你这个可恶的卖国奴！我要让你尽情品尝安全局的特别审讯手段！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Haha, wie kannst du es nur wagen, du abartige Verräterin! Lass mich dir einen kleinen Vorgeschmack auf den speziellen Verhörkurs geben, auf den das Sicherheitsbüro so stolz ist."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Hé hé. Tu n'es qu'une traîtresse, je le savais depuis le début ! Prépare-toi à souffrir, car le Bureau est réputés pour ses interrogatoires... bien corsés !"
L38_1.m_Talk_FRA = L39_1
