L40_1 = "m_Crash"
L39_1[L40_1] = 20
L40_1 = "아이고, 목숨만 살려 주십쇼! 다 먹고 살자고 하는 짓 아니겠습니까요!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "おねがいします！！　命だけはごかんべんを！！　それもこれも食べていくために仕方なかったんです！！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Oh no! Please, have mercy! I only did what I did to put food on the table!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "哎呀～大人饒命啊！我也是為了求生存的嘛！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "โอ้ ไม่นะคะ! ขอร้องล่ะค่ะ! ปรานีฉันด้วย ฉันแค่ทำไปเพื่อปากท้องตัวเองเท่านั้น!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Ôi không! Xin hãy thương xót! Tôi chỉ làm những gì tôi phải làm để kiếm ăn!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "哦不！求求你饶了我吧！我也是被逼无奈的！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Oh nein! Bitte, verschonen Sie mich! Ich habe das doch nur getan, um zu überleben!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oh non ! S'il vous plaît, ayez pitié ! Si j'ai agi ainsi, c'était seulement parce que je veux VIVRE !"
L39_1.m_Talk_FRA = L40_1
