L43_1 = "UNIT_HATE"
L42_1.m_Face = L43_1
L43_1 = "ROOKIE_GRONIA_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "……아, 속 쓰려. 위에 구멍 날 것 같아."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……あ、お腹痛い。胃に穴が開きそう。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "...Ah, my heart can’t take any more of this..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "……嗚，想到就覺得胃痛！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "...อาห์ ปวดใจดังไฟสุมทรงทะลวงอกฉัน..."
L42_1.m_Talk_THA = L43_1
L43_1 = "...Ah, trái tim tôi không thể chịu đựng thêm nữa ..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "……啊，身体好难受，肚子……肚子感觉破了个洞。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "... Ah, mein Bauch tut so weh. Ich fühlt sich so an, als wäre ein Loch in meinem Magen."
L42_1.m_Talk_DEU = L43_1
L43_1 = "...Ah, j'en peux plus... je crois que je vais gerber, là..."
L42_1.m_Talk_FRA = L43_1
