L46_1 = "GRONIA_ACT3_INTERLUDE1@95#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 95
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 4100301
L45_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L46_1 = "UNIT_LAUGH"
L45_1.m_Face = L46_1
L46_1 = "ROOKIE_GRONIA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "고향에 부모님이 계세요. 배급도 잘 안 나오는 시골이라 돈이라도 부쳐 줘야 하거든요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "故郷に両親がいるんですが。配給もあまりよく配られない田舎なんで、お金でも送らないとダメなんです。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "My parents are still living out in my hometown. They don’t distribute many rations out there, so I have to send them money from time to time."
L45_1.m_Talk_ENG = L46_1
L46_1 = "因為我爸媽住在老家，鄉下地方配給也不多，所以我有錢都會寄回家。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "พ่อแม่ฉันยังอยู่ที่บ้านเกิด อยู่ที่นั่นพวกท่านก็ไม่ได้รับปันส่วนเท่าไหร่ บางครั้งฉันก็เลยต้องส่งเงินให้บ้างน่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Cha mẹ tôi vẫn đang sống ở quê nhà. Họ không phân phối nhiều khẩu phần ăn ở đó, vì vậy thỉnh thoảng tôi phải gửi tiền cho họ."
L45_1.m_Talk_VTN = L46_1
L46_1 = "……因为父母还住在乡下，食物分配不稳定，所以只能由我来补贴家用。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Meine Eltern leben immer noch in meiner Heimatstadt. Sie verteilen nicht so viele Rationen da draußen, daher muss ich ihnen von Zeit zu Zeit Geld schicken."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Mes parents vivent toujours au bled. Les ravitaillements sont rares là-bas, alors je dois bien les aider comme je peux."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "GRONIA_ACT3_INTERLUDE1@96#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 96
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 4100301
L46_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L46_1.m_bWaitClick = true
