L47_1 = "UNIT_LAUGH"
L46_1.m_Face = L47_1
L46_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "아하. 수도 출신이 아니었구나."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "へえ。首都生まれじゃなかったんだ？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Oh! So you’re a country girl."
L46_1.m_Talk_ENG = L47_1
L47_1 = "原來如此，你也不是在首都土生土長的。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "โอ๊ะ! เธอเป็นน้องนางบ้านนาสินะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ồ! Vậy cô là một cô gái quê."
L46_1.m_Talk_VTN = L47_1
L47_1 = "啊哈。原来你不是首都出身啊。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Oh! Du bist also ein Mädchen vom Lande."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Oh, alors tu n'es pas d'ici ?"
L46_1.m_Talk_FRA = L47_1
