L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 99
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 4100301
L49_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
