L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L50_1 = "L"
L49_1.m_Pos = L50_1
L50_1 = "그렇다면 어쩔 수 없지. 당분간은 우리 집에서 지내."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それなら仕方ないね。しばらくウチで泊ってもいいよ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "If that’s the case, no worries! Feel free to crash at my place."
L49_1.m_Talk_ENG = L50_1
L50_1 = "那好吧，你就暫時住在我家吧。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ถ้างั้นก็ไม่ต้องห้วงเลย! พักบ้านฉันได้ตามสบายเลยนะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Nếu đúng như vậy, không phải lo lắng! Hãy cứ thoải mái ở lại chỗ của tôi."
L49_1.m_Talk_VTN = L50_1
L50_1 = "没办法。那你就暂住在我家吧。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Wenn das der Fall ist, keine Sorge! Fühl dich wie zu Hause."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Il fallait le dire tout de suite ! Dans ce cas, tu peux rester chez moi."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "GRONIA_ACT3_INTERLUDE1@100#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L50_1.m_CutScenProcessKey = 100
L50_1.m_CutScenID = 4100301
L50_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "ROOKIE_GRONIA_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "R"
L50_1.m_Pos = L51_1
L51_1 = "……의외로 선뜻 허락해 주시네요."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "……意外とすんなり許可してくれるんですね。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "...Wow, you’re actually going to let me stay at your home?"
L50_1.m_Talk_ENG = L51_1
L51_1 = "……沒想到你答應得這麼爽快。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "...โห เธอจะให้ฉันนอนบ้านเธอจริงๆ เหรอ?"
L50_1.m_Talk_THA = L51_1
L51_1 = "...Wow, cô thực sự sẽ để tôi ở nhà của cô?"
L50_1.m_Talk_VTN = L51_1
L51_1 = "……对不起，但是我实在没地方……哎？你就这么轻易答应了吗？"
L50_1.m_Talk_SCN = L51_1
L51_1 = "... Sie lassen mich tatsächlich bei Ihnen übernachten?"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Euh... vous êtes sûre ?"
L50_1.m_Talk_FRA = L51_1
