L2_1 = "GRONIA_ACT3_INTERLUDE1@101#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 101
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 4100301
L1_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L2_1 = "L"
L1_1.m_Pos = L2_1
L2_1 = "후훗. 당연하지. 같이 흙먼지 들이마시면서 싸운 파트너인걸."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ふふっ。当たり前でしょ？　一緒に土埃吸いながら戦ったパートナーだもん。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Of course! We’re partners after all."
L1_1.m_Talk_ENG = L2_1
L2_1 = "呵呵，那還用說，誰叫我們是一起並肩作戰的夥伴。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แหงสิ! ยังไงเราก็คู่หูกันนี่"
L1_1.m_Talk_THA = L2_1
L2_1 = "Tất nhiên! Dù gì thì chúng ta cũng là đối tác của nhau."
L1_1.m_Talk_VTN = L2_1
L2_1 = "当然啦。毕竟我们是并肩作战过的伙伴嘛！"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Natürlich! Wir sind schließlich Partner."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Bien entendu. On est partenaires, non ?"
L1_1.m_Talk_FRA = L2_1
