L4_1 = "GRONIA_ACT3_INTERLUDE1@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4100301
L3_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "그래, 파트너. 입에 안 붙으면 전우라고 해도 되고."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そう、パートナー。気まずかったら戦友でもいいよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "That’s right. Partners. If you don’t like that word, you can call us comrades."
L3_1.m_Talk_ENG = L4_1
L4_1 = "對啊，夥伴，還是你不習慣的話，也可以說是戰友。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "แม่นแล้วคู่หู ถ้าไม่ชอบคำนั้นเดี๋ยวเรียกสหายก็ได้"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đúng rồi. Đối tác. Nếu cô không thích từ đó, cô có thể gọi chúng ta là đồng chí."
L3_1.m_Talk_VTN = L4_1
L4_1 = "是啊，伙伴。如果不习惯，你也可以说是战友。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "So ist es. Partner. Wenn dir dieses Wort nicht gefällt, können wir uns auch Kameraden nennen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Oui, partenaires. Si le mot ne te plaît pas, tu peux en choisir un autre. Camarades, collègues..."
L3_1.m_Talk_FRA = L4_1
