L7_1 = "GRONIA_ACT3_INTERLUDE1@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 4100301
L6_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
