L7_1 = "UNIT_LAUGH"
L6_1.m_Face = L7_1
L7_1 = "BASS_HARMONY_NULL_HIDE"
L6_1.m_CharStrID = L7_1
L7_1 = "R"
L6_1.m_Pos = L7_1
L7_1 = "레아, 일 얘기 끝나려면 아직 멀었어?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "レア、仕事の話はまだ？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Leah, are you almost done with your work talk?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "蕾亞，你事情還沒談完嗎？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "เลอาห์ค่ะ คุยงานใกล้เสร็จรึยังคะ?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Leah, cậu sắp nói xong về công việc của mình chưa?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "蕾娅，工作的事情还没聊完吗？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Leah, redest du etwa noch immer über die Arbeit?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Leah, tu en as encore pour longtemps ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "GRONIA_ACT3_INTERLUDE1@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 4100301
L7_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "BASS_HARMONY_NULL_HIDE"
L7_1.m_CharStrID = L8_1
L8_1 = "R"
L7_1.m_Pos = L8_1
L8_1 = "온몸이 먼지투성이잖아. 얼른 씻어야지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "全身埃まみれじゃない。早くお風呂に入って。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Your body’s covered in dirt. Hurry up and get yourself cleaned up."
L7_1.m_Talk_ENG = L8_1
L8_1 = "看你全身髒兮兮的，還不趕快沖洗一下。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ตัวคุณเปื้อนไปหมดเลยค่ะ รีบไปอาบน้ำเถอะนะคะ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Người cậu phủ đầy bụi. Nhanh lên và vệ sinh sạch sẽ đi nào."
L7_1.m_Talk_VTN = L8_1
L8_1 = "看你全身都是灰，快点去洗洗吧？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Dein ganzer Körper ist mit Staub bedeckt. Na los! Geh dich schnell duschen."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Regarde-moi ça, tes vêtements sont tous crasseux. Va prendre une douche, tu veux bien ?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
