L9_1 = "BASS_HARMONY_NULL_HIDE"
L8_1.m_CharStrID = L9_1
L9_1 = "R"
L8_1.m_Pos = L9_1
L9_1 = "하여튼 집에선 늦장꾸러기에 게으름뱅이라니까."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "まったく、家ではもたもたしてるし、なまけ者なんだから。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Leah really is pretty lazy around the house."
L8_1.m_Talk_ENG = L9_1
L9_1 = "你在家就是這麼不修邊幅，又髒又懶！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อยู่บ้านแล้วเลอาห์ขี้เกียจจริงๆ เลย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Leah thực sự khá lười khi ở nhà."
L8_1.m_Talk_VTN = L9_1
L9_1 = "真是的，蕾娅一回家就变成了大懒猫！"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Leah ist wirklich ziemlich faul, wenn sie zu Hause ist."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Elle ne fait vraiment aucun effort pour maintenir l'endroit propre..."
L8_1.m_Talk_FRA = L9_1
