L10_1 = "UNIT_SURPRISE"
L9_1.m_Face = L10_1
L10_1 = "OLD_GRONIA_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "으응, 레아 말대로 귀여운 손님이 오셨네……."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "うん、レアの言うとおりかわいいお客さんが来たのね……"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Ahh, Leah brought a pretty guest home..."
L9_1.m_Talk_ENG = L10_1
L10_1 = "嗯嗯，蕾亞說會帶一位可愛的客人會來……"
L9_1.m_Talk_TWN = L10_1
L10_1 = "อ้าว ดูสิ เลอาห์พาแขกคนสวนกลับมาบ้านด้วย..."
L9_1.m_Talk_THA = L10_1
L10_1 = "Ahh, Leah đã đưa một vị khách xinh đẹp về nhà..."
L9_1.m_Talk_VTN = L10_1
L10_1 = "嗯，果然和蕾娅说的那样，来了位可爱的客人……"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ahh, Leah hat ja wirklich einen niedlichen Gast mit nach Hause gebracht ..."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oh, Leah a amenée une invitée ? Qu'elle est mignonne, cette petite..."
L9_1.m_Talk_FRA = L10_1
