L10_1.m_CharStrID = L11_1
L11_1 = "L"
L10_1.m_Pos = L11_1
L11_1 = "오늘 식사는……. 맛있게 차려야겠어요……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "今日の食事は……美味しいものを作らないとね……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "I’ll need to make something special... tonight for dinner…"
L10_1.m_Talk_ENG = L11_1
L11_1 = "那……今要多煮幾道菜……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ตายจริง สงสัยอาหารเย็นคืนนี้ต้องทำอะไรพิเศษหน่อยแล้ว"
L10_1.m_Talk_THA = L11_1
L11_1 = "Ôi trời, tối nay tôi sẽ cần làm một món gì đó đặc biệt... cho bữa tối."
L10_1.m_Talk_VTN = L11_1
L11_1 = "哎呀，今天的晚餐……我要好好准备料理才行……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Ich muss etwas Besonderes heute Abend zum Abendessen vorbereiten ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Je vais devoir préparer quelque chose de spécial pour le dîner de ce soir..."
L10_1.m_Talk_FRA = L11_1
