L14_1 = "알겠어, 안젤라. 곧 들어갈게."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "わかったよ、アンジェラ。すぐ入る。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Okay, Angela. We’ll be in soon."
