L14_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L15_1 = "L"
L14_1.m_Pos = L15_1
L15_1 = "중사, 갈아입을 옷은 있어?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "軍曹、着替えはある？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Sergeant, you have a change of clothes?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "中士，你有衣服可以替換嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "เธอมีเสื้อผ้ามาเปลี่ยนรึเปล่าจ่า?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Trung sĩ, cô có thay quần áo không?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "中士，你有能换洗的衣物吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Unteroffizierin, hast Kleidung zum Wechseln dabei?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Sergente, tu as des vêtements de rechange ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "GRONIA_ACT3_INTERLUDE1@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4100301
L15_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "UNIT_SURPRISE"
L15_1.m_Face = L16_1
L16_1 = "ROOKIE_GRONIA_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "R"
L15_1.m_Pos = L16_1
L16_1 = "m_Crash"
L15_1[L16_1] = 20
L16_1 = "네? 저도 같이 들어가요?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "え？　私も一緒に入るんですか？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Wait? I’m showering with you?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "嗯？我也一起去洗嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "หา? ฉันต้องอาบน้ำกับเธอเหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chờ đã? Tôi sẽ tắm với cô?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "啊……？我也要一起洗吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Wie bitte? Ich dusche mit Ihnen zusammen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Euh... on va pas se doucher ensemble, quand même ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "GRONIA_ACT3_INTERLUDE1@116#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4100301
L16_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L17_1 = "L"
L16_1.m_Pos = L17_1
L17_1 = "타나베린이 시골보다 사정이 낫긴 해도, 돌아가면서 씻을 만큼 사치 부릴 정도는 아냐."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "タナベリンが田舎よりはマシでも、贅沢に一人ずつお風呂に入れるほどではないからね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Tanaberin’s situation might be better than the countryside’s, but not enough to take your own showers."
L16_1.m_Talk_ENG = L17_1
L17_1 = "達那貝林的情況是比鄉下好，但也沒有奢侈到可以輪流洗澡好嗎！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "สถานการณ์ในแทนาเบอรินอาจดีกว่าที่บ้านนอก แต่ก็ไม่ดีพอให้อาบน้ำเองคนเดียวหรอกนะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tình hình của Tanaberin có thể tốt hơn vùng nông thôn, nhưng vẫn không đủ để cô tắm một mình."
L16_1.m_Talk_VTN = L17_1
L17_1 = "特纳贝林虽然比乡下好一些，但也没奢侈到可以轮流洗澡。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Obwohl die Situation in Tanaberin besser ist als auf dem Land, reicht es nicht aus, sich den Luxus des separaten Duschens zu gönnen."
L16_1.m_Talk_DEU = L17_1
L17_1 = "La situation à Tanaberin est peut-être meilleure qu'à la campagne, mais on doit quand même rationner l'eau."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "GRONIA_ACT3_INTERLUDE1@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 4100301
L17_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L18_1 = "L"
L17_1.m_Pos = L18_1
L18_1 = "씻다가 언제 물이 끊길지 모르거든. 씻을 수 있을 때 몰아서 씻어야지."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "いつ断水になるかわからないからさ。できる時にお風呂に入らないと。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "You never know when the water will get turned off. So when the water’s working, we all need to wash together."
L17_1.m_Talk_ENG = L18_1
L18_1 = "誰知道會不會洗到一半突然停水，當然要趁有水的時候，趕快一起洗！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "เราไม่รู้เลยว่าน้ำจะหยุดไหลตอนไหน ดังนั้น เราทุกคนก็ต้องอาบด้วยกันตอนมันยังไหลอยู่นี่แหละ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Cô không bao giờ biết khi nào nước sẽ tắt. Vì vậy, khi nước hoạt động, tất cả chúng ta cần phải tắm rửa cùng nhau."
L17_1.m_Talk_VTN = L18_1
L18_1 = "而且也不知道什么时候断水。得在能洗澡的时候赶紧一起洗。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Man weiß nie, wann das Wasser abgestellt wird. Solange das Wasser funktioniert, müssen wir alle zusammen duschen."
L17_1.m_Talk_DEU = L18_1
L18_1 = "On ne sait jamais quand elle sera coupée, tu comprends ? Alors on prend des douches groupées pour l'économiser le plus possible."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "GRONIA_ACT3_INTERLUDE1@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4100301
L18_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_DESPAIR"
L19_1 = "ROOKIE_GRONIA_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "R"
L18_1.m_Pos = L19_1
L19_1 = "갑자기 군 병원이 그리워지는데요……."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "急に軍病院が恋しくなりました……"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Suddenly, I find myself missing that military hospital..."
L18_1.m_Talk_ENG = L19_1
L19_1 = "突然有點想念軍醫院……"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อยู่ๆ ก็คิดถึงโรงพยาบาลทหารขึ้นมาเลยฉัน"
L18_1.m_Talk_THA = L19_1
L19_1 = "Đột nhiên, tôi thấy mình nhớ bệnh viện quân y đó..."
L18_1.m_Talk_VTN = L19_1
L19_1 = "我突然有点怀念军区医院了……"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Plötzlich vermisse ich das Militärkrankenhaus ..."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Finalement il était peut-être pas si mal, cet hôpital..."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
