L22_1 = "GRONIA_ACT3_INTERLUDE1@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 4100301
L21_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L22_1 = "어때, 물 온도는? 너무 뜨겁지는 않아?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "湯加減はどう？　熱すぎない？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "How’s the water temperature? Not too hot?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "水溫還可以嗎？會不會太燙？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "น้ำเป็นไง? ไม่ร้อนไปใช่มั้ย?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Nhiệt độ nước thế nào? Không quá nóng?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "怎么样，水的温度不是很烫吧？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Wie ist die Wassertemperatur? Nicht zu heiß?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Comment est la température ? Ça va, c'est pas trop chaud ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "GRONIA_ACT3_INTERLUDE1@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 4100301
L22_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "ROOKIE_GRONIA_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "네. 입대할 때 느꼈지만 이렇게나마 씻는 게 어디냐 싶네요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "はい。入隊の時もそうでしたけど、こうやってお風呂に入れるだけでも贅沢です。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "It’s fine. At least I’m thankful for the fact that I’m able to take a shower like this."
L22_1.m_Talk_ENG = L23_1
L23_1 = "水溫可以，我進到部隊時就有這種感覺，怎麼會是這樣洗澡的？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ได้อยู่แหละ ก็ยังดีที่อย่างน้อยฉันอาบน้ำแบบนี้ได้"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tốt rồi. Ít nhất thì tôi cũng biết ơn vì tôi có thể tắm như thế này."
L22_1.m_Talk_VTN = L23_1
L23_1 = "呃，还好……我们新兵刚入伍的第一课，就是有澡洗就该感到庆幸。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ja. Als ich in der Armee war, konnte ich mich nicht einfach so duschen, weshalb ich dankbar dafür bin, mich jetzt so duschen zu können."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Ouais, ça ira. C'est déjà pas mal de pouvoir prendre une douche, alors je vais pas me plaindre..."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "GRONIA_ACT3_INTERLUDE1@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 4100301
L23_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "ROOKIE_GRONIA_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "안면 튼 지도 얼마 안 된 사람이랑 알몸으로 있다는 수치심 정도는 깜빡해 버렸다고나 할까요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "知り合ったばかりの人と全裸でいるっていう恥ずかしさなんて、一瞬忘れてたというか。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Ugh. I forgot how embarrassing this is, being naked with something you haven’t even known for that long."
L23_1.m_Talk_ENG = L24_1
L24_1 = "跟一個見沒幾次面的人坦誠相見，連羞恥兩個字都忘記怎麼寫。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "โอ้ย ลืมไปแล้วนะนี่ว่ามันน่าอายขนาดนั้น การต้องมาแก้ผ้ากับอะไรที่ตัวเองก็เพิ่งรู้จักได้ไม่นานน่ะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ặc. Tôi quên mất điều này đáng xấu hổ như thế nào, khỏa thân với một người mới quen."
L23_1.m_Talk_VTN = L24_1
L24_1 = "跟不熟悉的人一起赤身相对的羞耻感，也是尽快抛掉比较好。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Ich habe vergessen, wie unangenehm es ist, vor jemandem nackt zu sein, den ich noch nicht so lange kenne."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Par contre, c'est quand même un peu gênant d'être nue ici avec vous alors qu'on se connaît à peine..."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "GRONIA_ACT3_INTERLUDE1@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 4100301
L24_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L25_1 = "후훗. 꽤나 의식하네."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ふふっ。結構意識するのね。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Fuu fuu... You’re so self-conscious."
L24_1.m_Talk_ENG = L25_1
L25_1 = "呵呵，你還會在意這種事喔？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฮุฮุ... เธอนี่ขี้อายจังนะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Phư phư... Cô biết ý quá."
L24_1.m_Talk_VTN = L25_1
L25_1 = "呼呼，看来你很在意。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Hahaha ... Du bist so unsicher."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Hu hu... Tu es plus pudique que tu en as l'air."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "GRONIA_ACT3_INTERLUDE1@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 4100301
L25_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L26_1 = "혹시 동성 취향이야?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "もしかして同性が好きとか？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Wait a second... Are you into girls?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "難道你喜歡女生嗎？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เดี๋ยวนะ... เธอชอบผู้หญิงเหรอ?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Chờ một chút... Cô có thích con gái không?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "你不会喜欢女孩子吧，中士？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Moment … Kann es sein, dass du auf Frauen stehst?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Ou alors c'est parce que tu aimes les filles ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "GRONIA_ACT3_INTERLUDE1@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 4100301
L26_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "ROOKIE_GRONIA_NULL_NULL"
L26_1.m_CharStrID = L27_1
L27_1 = "글쎄요. 취향을 단언할 만큼 남한테 진지하게 관심 가져 본 적은 없어서요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "どうでしょうね。断言できるほど本気で他人に興味を持ったことがないですから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I don’t know. I’ve never been attracted to someone enough to know."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我也不知道，因為我從來沒有喜歡過誰。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ไม่รู้สิ แต่ก็ไม่เคยสนใจใครจนอยากรู้เลยนะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi không biết. Tôi chưa bao giờ bị thu hút bởi một người đủ để biết có hay không."
L26_1.m_Talk_VTN = L27_1
L27_1 = "这、这个……我还没有和别人认真相处过。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich weiß nicht. Ich habe mich noch nie richtig zu jemandem hingezogen gefühlt, um zu wissen, auf wen ich stehe."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Aucune idée. J'ai jamais été assez attirée par quelqu'un pour le savoir."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "GRONIA_ACT3_INTERLUDE1@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 4100301
L27_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "ROOKIE_GRONIA_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "남들한테 한눈 팔기에는 하루하루 살아남기도 빠듯했고요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "毎日生き延びるのにギリギリで、そんな暇なかったです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "It was so difficult just to get by day by day, I never really had any time for that kind of stuff."
L27_1.m_Talk_ENG = L28_1
L28_1 = "每天光是要活下去就已經很辛苦，哪還有心思花在別人身上。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เอาตัวให้รอดไปวันๆ ก็ยากจะแย่ ฉันเลยไม่เคยมีเวลาคิดเรื่องนั้นจริงๆ จังๆ เลยน่ะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Thật khó khăn để sống sót từng ngày, tôi thực sự chưa bao giờ có thời gian cho những thứ đó."
L27_1.m_Talk_VTN = L28_1
L28_1 = "每天都是在生死的边缘游荡，所以也没有闲心去想这些……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich war zu beschäftigt damit, Tag für Tag zu überleben, weshalb ich nie wirklich Zeit für solche Sachen hatte."
L27_1.m_Talk_DEU = L28_1
L28_1 = "J'suis déjà suffisamment occupée à survivre, j'ai pas vraiment le temps pour ce genre de choses."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "GRONIA_ACT3_INTERLUDE1@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 4100301
L28_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L29_1 = "하긴. 이 나라 사람들은 대부분 그렇지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "確かに。この国の人は たいていそうよね。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Fair enough. I guess most people in this country are in the same situation."
L28_1.m_Talk_ENG = L29_1
L29_1 = "也對，這個國家的人應該大部分都是如此。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ก็จริงนะ ฉันว่าคนประเทศนี้ส่วนใหญ่ก็สภาพเดียวกันนี่แหละ"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cũng đúng. Tôi đoán hầu hết mọi người ở đất nước này đều đang ở trong tình trạng tương tự."
L28_1.m_Talk_VTN = L29_1
L29_1 = "说的也是。这个国家的人，大部分都是这样吧。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Das macht Sinn. Ich denke, den meisten Menschen in diesem Land geht es genauso."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Comme la plupart des gens de ce pays, j'imagine..."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
