L32_1 = "GRONIA_ACT3_INTERLUDE1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 4100301
L31_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L32_1 = "침식체 군집이라도 나타났나 보네. 한동안 뜸하긴 했지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "侵食体の群れでも現れたのかな？　最近まばらだったし。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Sounds like a cluster of Corrupted objects has been detected. It’s been a while."
L31_1.m_Talk_ENG = L32_1
L32_1 = "可能是有侵蝕體出現，有段時間比較少出現的說。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เสียงเหมือนตรวจจับกลุ่มวัตถุคอร์รัปต์นะ ดังมาพักแล้ว"
L31_1.m_Talk_THA = L32_1
L32_1 = "Có vẻ như một bầy Vật Thể Ăn Mòn đã được phát hiện. Đã một thời gian rồi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "别紧张。应该是出现了侵蚀体群。好像已经有一阵子没听过类似的警报了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ein Cluster von Counterside-Objekten scheint entdeckt worden zu sein. Es ist eine Weile her."
L31_1.m_Talk_DEU = L32_1
L32_1 = "On dirait qu'il y a des O.C. en ville. Ça faisait longtemps."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "GRONIA_ACT3_INTERLUDE1@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 4100301
L32_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "ROOKIE_GRONIA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "……레버넌트 씨."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "……レヴナントさん。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "...Revenant."
L32_1.m_Talk_ENG = L33_1
L33_1 = "……亡靈小姐。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "...เรเวแนนต์"
L32_1.m_Talk_THA = L33_1
L33_1 = "...Revenant."
L32_1.m_Talk_VTN = L33_1
L33_1 = "……亡灵。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Revenant ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Revenant..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "GRONIA_ACT3_INTERLUDE1@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 4100301
L33_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L34_1 = "응?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "うん？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "What’s up?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "幹嘛？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "มีอะไรเหรอ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Có chuyện gì vậy?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "嗯？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ja, was denn?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Hmm ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "GRONIA_ACT3_INTERLUDE1@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 4100301
L34_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "ROOKIE_GRONIA_NULL_NULL"
L34_1.m_CharStrID = L35_1
L35_1 = "등에, 상처가……."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "背中に、傷が……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Those scars... On your back..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你背上的傷……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แผลเป็น... บนหลังเธอ..."
L34_1.m_Talk_THA = L35_1
L35_1 = "Những vết sẹo... Trên lưng của cô..."
L34_1.m_Talk_VTN = L35_1
L35_1 = "你背后的伤……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Diese Narben ... auf Ihrem Rücken ..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ces cicatrices sur votre dos..."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "GRONIA_ACT3_INTERLUDE1@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4100301
L35_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L36_1 = "아. 신경 쓰지 마. 침식체가 아니라 엄마가 낸 거니까."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "ああ。気にしないで。侵食体じゃなくてお母さん。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Ah. Don’t worry about those. Those aren’t from a Corrupted Object or anything. My mom gave me those."
L35_1.m_Talk_ENG = L36_1
L36_1 = "喔～這沒什麼啦，這不是侵蝕體弄的，是我媽抓的。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "อ๋อ ไม่ต้องสนใจหรอก ไม่ได้โดนวัตถุคอร์รัปต์หรืออะไรมา ฝีมือแม่ฉันนี่แหละ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Ah. Đừng lo lắng về chuyện đó. Những thứ đó không phải do Vật Thể Ăn Mòn hay gì đâu. Mẹ tôi đã tạo ra chúng."
L35_1.m_Talk_VTN = L36_1
L36_1 = "啊，别担心。那个是被妈妈弄伤的。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ah. Mach dir keine Sorgen. Diese stammen nicht von einem Counterside-Objekt. Meine Mutter gab mir diese."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oh, ne t'en fais pas pour ça. C'est pas les Objets Corrompus, c'est ma mère."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "GRONIA_ACT3_INTERLUDE1@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 4100301
L36_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "ROOKIE_GRONIA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "어머니요? 그 휠체어 타고 계시던 분 말이에요?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "お母さん？　あの車椅子に座ってた方ですか？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Your mom? That woman in a wheelchair?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "你媽媽？那位坐在輪椅上的女士？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฝีมือแม่เธอเหรอ? ผู้หญิงที่นั่งรถเข็นนั่นอะนะ?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Mẹ của cô? Người phụ nữ ngồi xe lăn đó?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "妈妈？就是那位坐轮椅的阿姨？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ihre Mutter? Diese Dame im Rollstuhl meinen Sie?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Votre... mère ? Cette dame en fauteuil roulant ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "GRONIA_ACT3_INTERLUDE1@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 4100301
L37_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L38_1 = "응. 과도한 스트레스로 인한 정신질환이래. 증상만 보면 영락없는 치매야."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "うん。ストレス過剰による精神病だって。症状を見れば間違いなく認知症だよ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Yup. The doctors said it’s because of a mental illness triggered by the extreme stress her dementia gives her."
L37_1.m_Talk_ENG = L38_1
L38_1 = "嗯，她因為壓力過大導致精神疾病，看症狀很明顯就是失智症。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อื้อ หมอบอกว่าอาการป่วยทางจิตของแม่เกิดเพราะความเครียดสุดขีดจากภาวะสมองเสื่อมน่ะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đúng vậy. Các bác sĩ cho biết đó là do căn bệnh tâm thần gây ra bởi sự căng thẳng tột độ mà chứng mất trí nhớ mang lại cho bà ấy."
L37_1.m_Talk_VTN = L38_1
L38_1 = "嗯，医生说我妈妈是过度压力引起的精神疾病。犯病症状就和老年痴呆一样。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Jawohl. Es ist eine psychische Erkrankung, die durch übermäßigen Stress verursacht wird. Es ist definitiv Demenz, wenn man sich die Symptome ansieht."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Ouais. Elle a parfois des épisodes de démence et d'amnésie, quand elle est trop stressée par quelque chose."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "GRONIA_ACT3_INTERLUDE1@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 4100301
L38_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L39_1 = "숨겨 놓은 딸을 내놓으라면서, 이렇게 등을 그어댔지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "隠している娘を出せって、こうやって背中を引っかいたの。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "She screamed at me telling me to give her back her daughter while doing this to my back."
L38_1.m_Talk_ENG = L39_1
L39_1 = "她一邊說把我女兒交出來，一邊把我的背抓成這樣。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "เธอเลยกรี๊ดๆ ใส่ฉัน บอกให้ฉันคืนลูกสาวมาแล้วก็ทำแบบนี้กลับหลังฉันไปด้วย"
L38_1.m_Talk_THA = L39_1
L39_1 = "Bà ấy đã hét vào mặt tôi bảo tôi trả lại con gái cho bà ấy trong khi làm thế với lưng tôi."
L38_1.m_Talk_VTN = L39_1
L39_1 = "有时会突然以为还是年轻时候的自己。有次她哭喊着要我把女儿还给她，把我的背抓成了这样。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Sie schrie mich an mich und sagte mir, ich solle ihr ihre Tochter zurückgeben, während sie mir auf den Rücken schlug."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ces marques, elles me les a faites un jour en me criant de lui rendre sa fille."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
