L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 4100301
L40_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L41_1 = "그 날은 너무 힘들어서……. 엄마를 죽인 다음에 나도 죽으려고 했어."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "その日は辛すぎて……お母さんを殺して私も死のうとしたんだ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "At that terrible day... I planned to kill my mom and then myself."
L40_1.m_Talk_ENG = L41_1
L41_1 = "那天我真的好累……甚至想先殺死媽媽後，我再自殺。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "วันนั้นมันแย่มาก และหลังจากนั้น... ฉันก็วางแผนจะฆ่าแม่ แล้วฆ่าตัวตายตาม"
L40_1.m_Talk_THA = L41_1
L41_1 = "Vào cái ngày khủng khiếp đó... Tôi đã lên kế hoạch giết mẹ rồi tự tử."
L40_1.m_Talk_VTN = L41_1
L41_1 = "那天我真的好累……甚至想先杀死妈妈后，再自杀算了。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "An diesem schrecklichen Tag ... plante ich, meine Mutter und dann mich selbst zu töten."
L40_1.m_Talk_DEU = L41_1
L41_1 = "La violence était telle que j'ai essayer de la tuer un instant, avant de mettre fin à mes jours..."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "GRONIA_ACT3_INTERLUDE1@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 4100301
L41_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L42_1 = "그걸 막아 준 사람이 아까 본 안젤라야."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "それを止めてくれたのがさっき会ったアンジェラ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "The one who stopped me was Angela, the girl you met earlier."
L41_1.m_Talk_ENG = L42_1
L42_1 = "而阻止這件事發生的人，就是你剛才看到的安潔拉。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "คนที่หยุดฉันไว้ก็แอนเจลานี่แหละ ที่เธอเจอเมื่อกี้น่ะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Người ngăn tôi lại là Angela, cô gái mà cô đã gặp lúc nãy."
L41_1.m_Talk_VTN = L42_1
L42_1 = "还好安吉拉阻止了我。啊……就是你刚刚见过的那个女孩子。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Diejenige, der mich davon abgehalten hat, war Angela, das Mädchen, das du vorhin getroffen hast."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais heureusement, Angela m'a arrêtée à temps. C'est la fille que tu as vu tout à l'heure."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "GRONIA_ACT3_INTERLUDE1@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 4100301
L42_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "ROOKIE_GRONIA_NULL_NULL"
L42_1.m_CharStrID = L43_1
L43_1 = "……그래서 첫눈에 반해 동성 취향이 됐다는 결론인가요?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "……それで一目惚れして同性に目覚めたんですか？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "...And when you first saw her, you developed an interest in girls?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "……所以你對她一見鍾情，然後就喜歡上女生喔？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "...พอเจอกันครั้งแรก เธอก็เริ่มสนใจผู้หญิงเหรอ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "...Và khi lần đầu tiên nhìn thấy cô ấy, cô đã nảy sinh hứng thú với các cô gái?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "……所以，你们一见钟情，在一起生活了对吧？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "... Und als Sie sie zum ersten Mal gesehen haben, haben Sie ein Interesse an Frauen entwickelt?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "... Et du coup vous êtes tombée amoureuse d'elle ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "GRONIA_ACT3_INTERLUDE1@143#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4100301
L43_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L44_1 = "후훗. 그게 그렇게 이어지나?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ふふっ。そう繋がる？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Fuu fuu. Is that what you think?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "呵呵，是這樣說嗎？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ฮุฮุ คิดงั้นเหรอ?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ha ha. Có phải đó là những gì cô nghĩ?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "呵呵。你怎么会得出这样的结论？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Hahaha. Ist es das, was du denkst?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Hu hu. C'est ce que tu penses ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GRONIA_ACT3_INTERLUDE1@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4100301
L44_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "AGENT_GRONIA_NULL_NULL"
L45_1 = "마저 씻고 나와, 중사. 식사는 다 같이 모여서 해야지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "先に上がるから洗ってきて、軍曹。食事はみんなでしないと。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Finish washing up, Sergeant. We’re eating dinner as a family."
L44_1.m_Talk_ENG = L45_1
L45_1 = "趕快洗完出來吧，中士。吃飯的時候一定要大家聚在一起吃。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "อาบน้ำให้เสร็จเถอะจ่า เดี๋ยวไปกินข้าวกันฉันครอบครัว"
L44_1.m_Talk_THA = L45_1
L45_1 = "Tắm rửa cho xong đi, Trung sĩ. Chúng ta sẽ ăn tối như một gia đình."
L44_1.m_Talk_VTN = L45_1
L45_1 = "你慢慢洗吧，中士。等你出来我们就开饭。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Dusch dich fertig und komm dann raus, Unteroffizierin. Wir essen alle zusammen als Familie zu Abend."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Finis de te laver, sergente. Nous dînons en famille."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
