L49_1 = "SOLDIER_GRONIA_NULL_C"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "이 수송차량, 지금 어디로 가는 거지? 소속과 목적지를 밝혀라."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "この輸送車、どこへ向かう？　所属と目的地を言え。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Where is this transport headed? Identify yourselves."
L48_1.m_Talk_ENG = L49_1
L49_1 = "這台運輸車現在是要開去哪裡？說出所屬和目的地！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "รถขนส่งนี่จะไปไหนเนี่ย? แจ้งตัวตนมา"
L48_1.m_Talk_THA = L49_1
L49_1 = "Phương tiện giao thông này hướng đến đâu? Báo danh tính đi."
L48_1.m_Talk_VTN = L49_1
L49_1 = "这辆运输车要去哪？请表明身份和目的地。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wohin will dieses Transportfahrzeug fahren? Weis dich aus und sag mir, wohin du willst!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Quelle est votre destination ? Veuillez vous identifier."
L48_1.m_Talk_FRA = L49_1
