L3_1 = "GRONIA_ACT3_INTERLUDE1@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 4100301
L2_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "ROGUE_EXTRA_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "헤, 헤헤……. 저 소리 안 들리십니까?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "へ、へへ……あの音、聞こえませんか？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Hey, hey... Can you hear that sound?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "嘿嘿嘿……你沒聽到聲音嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เฮ้ยๆ... ได้ยินเสียงนั่นมั้ย?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Này, này... Cậu có nghe thấy âm thanh đó không?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "嘿，嘿嘿……你没听到那个警报吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Hey, hey ... Hören Sie denn nicht dieses Geräusch?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Hé, hé... Vous entendez de cruit ?"
L2_1.m_Talk_FRA = L3_1
