L4_1 = "GRONIA_ACT3_INTERLUDE1@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 4100301
L3_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "ROGUE_EXTRA_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "주거지역에 기어 들어온 침식체가 없는지 살펴보러 온 겁니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "住居区域へ入ってきた侵食体がないか調べに来たんですよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "We’re here to see if a Corrupted Object has made it into the residential area."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我們要去看居住區那裡是不是有侵蝕體入侵。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เรามาดูว่าวัตถุคอร์รัปต์บุกเข้าไปในพื้นที่อยู่อาศัยรึเปล่าน่ะ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Chúng tôi ở đây để xem liệu một Vật Thể Ăn Mòn có xâm nhập được vào khu dân cư hay không."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我们想来看看是不是有侵蚀体进入居民区了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Wir sind hier, um zu sehen, ob ein Counterside-Objekt ins Wohngebiet eingedrungen ist."
L3_1.m_Talk_DEU = L4_1
L4_1 = "On est là pour s'assurer que les Objets Corrompus ne pénètrent pas dans le quartier résidentiel."
L3_1.m_Talk_FRA = L4_1
