L7_1 = "ROGUE_EXTRA_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "L_M_I"
L6_1.m_Pos = L7_1
L7_1 = "자, 여기 우리 회사 명함이니 받아 두시고."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "どうぞ、うちの会社の名刺、受け取ってください。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Here are our company’s business cards."
L6_1.m_Talk_ENG = L7_1
L7_1 = "這是我們公司的名片，請收下。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "นี่นามบัตรบริษัทเรา"
L6_1.m_Talk_THA = L7_1
L7_1 = "Đây là danh thiếp của công ty chúng tôi."
L6_1.m_Talk_VTN = L7_1
L7_1 = "给，这是我们公司的名片。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Hier sind die Visitenkarten unseres Unternehmens."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tenez, voici la carte de notre entreprise."
L6_1.m_Talk_FRA = L7_1
