L7_1.m_CharStrID = L8_1
L8_1 = "L"
L7_1.m_Pos = L8_1
L8_1 = "따로 쓰시라고 봉투에 두둑하게 넣어 뒀습니다."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "チップを封筒に厚めに入れときました。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I even put some nice “stuff” in a separate envelope for you."
L7_1.m_Talk_ENG = L8_1
L8_1 = "信封裡是一點小意思，儘管拿去用。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ผมเอา “ของ” ดีๆ แยกใส่ซองมาให้ด้วย"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi thậm chí còn để một số “thứ” trong một phong bì riêng cho anh đấy."
L7_1.m_Talk_VTN = L8_1
L8_1 = "信封里的东西会让你满意的。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ich habe sogar ein paar nette „Sachen“ in einen separaten Umschlag für Sie gesteckt."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Et ça, c'est une petite enveloppe « spéciale », rien que pour vous."
L7_1.m_Talk_FRA = L8_1
