L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 4100301
L9_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L9_1.m_bWaitClick = true
