L10_1 = "SOLDIER_GRONIA_NULL_C"
L9_1.m_CharStrID = L10_1
L10_1 = "R"
L9_1.m_Pos = L10_1
L10_1 = "이런 푼돈으로 검문을 피하려고 들어? 전원 당장 하차한다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "こんな小銭で検問をパスしようとしたのか？　全員、すぐ車から降りろ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You think you can avoid an inspection for so little? Everyone, get out of the vehicle at once."
L9_1.m_Talk_ENG = L10_1
L10_1 = "這點錢就想打發我們？車上的人都給我下車！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "คิดว่าแค่นี้แล้วจะไม่โดนตรวจเหรอ? ทุกคน ลงมาจากรถเดี๋ยวนี้"
L9_1.m_Talk_THA = L10_1
L10_1 = "Cậu nghĩ rằng cậu có thể tránh một cuộc thanh tra với số tiền ít ỏi này? Mọi người ra khỏi xe ngay lập tức."
L9_1.m_Talk_VTN = L10_1
L10_1 = "你以为花点钱就能避开检查吗？全部下车。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Denkst du wirklich, du kannst eine Inspektion für so wenig vermeiden? Alle, müssen aus dem Fahrzeug aussteigen."
L9_1.m_Talk_DEU = L10_1
L10_1 = "J'ai une tête à recevoir des pots-de-vin ? Descendez du véhicule immédiatement."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
