L11_1 = "m_Crash"
L10_1[L11_1] = 15
L11_1 = "아, 저기. 그러시지 않는 게……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "あ、あの。そうしない方が……"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Oh, come on now. There’s no need for..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "哎唷～不要這樣……"
L10_1.m_Talk_TWN = L11_1
L11_1 = "โอ้ ไม่เอาน่า ไม่เห็นต้อง..."
L10_1.m_Talk_THA = L11_1
L11_1 = "Ồ, thôi nào. Không cần phải..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "啊，这不太好吧。最好还是……"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Oh, kommen Sie schon. Es besteht doch keine Notwendigkeit für ..."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Hmm. Si j'étais toi, j'aurais pas dit ça..."
