L13_1 = "MONTAGNE_ADMIN_NULL_SNIPER"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C"
L13_1 = "왜 그러지? 뭐가 문제야?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "どうした？　何かあるのか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "What’s going on? Is there a problem?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "發生什麼事？有什麼問題嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "เกิดอะไรขึ้นเหรอ? มีปัญหาอะไรรึเปล่า?"
L12_1.m_Talk_THA = L13_1
L13_1 = "Chuyện gì đang xảy ra vậy? Có vấn đề gì không?"
L12_1.m_Talk_VTN = L13_1
L13_1 = "怎么了？出了什么事？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Was ist los? Gibt es ein Problem?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Qu'y a-t-il ? Un problème ?"
