L16_1 = "GRONIA_ACT3_INTERLUDE1@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 4100301
L15_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "ROGUE_EXTRA_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "L_M_I"
L15_1.m_Pos = L16_1
L16_1 = "그, 그게 말이지, 나리. 여기 군인 분들이 우리 차를 좀 살펴 봐야겠다고 하시네."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "そ、それがさ、旦那。この軍人さん、うちの車を確認するっていうんだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "W-well... You see... These fine soldiers here say they need to inspect our vehicle."
L15_1.m_Talk_ENG = L16_1
L16_1 = "就…他們說要查我們的車子。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "กะ-ก็... คือ... ทหารคนเก่งพวกนี้บอกว่าต้องตรวจรถเราน่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Chà... Cô thấy đấy... Những người lính này nói rằng họ cần phải kiểm tra xe của chúng ta."
L15_1.m_Talk_VTN = L16_1
L16_1 = "是、是这样的，大人。这些军人说需要检查一下我们的车。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "N-nun ja ... Fräulein ... Diese Soldaten hier sagen, dass sie unser Fahrzeug inspizieren wollen."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Euh... C'est-à-dire que... Notre ami ici présent dit qu'il souhaiterait inspecter le véhicule."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "GRONIA_ACT3_INTERLUDE1@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 4100301
L16_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "MONTAGNE_ADMIN_NULL_SNIPER"
L16_1.m_CharStrID = L17_1
L17_1 = "R"
L16_1.m_Pos = L17_1
L17_1 = "돈은? 액수 제대로 찔러 준 거 맞아?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "金は？　ちゃんと渡したのか？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Huh? What about the money? Did you make sure to give the right amount?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "錢呢？錢給得夠多吧？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หือ? แล้วเงินล่ะ? ให้ไปพอรึเปล่า?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Huh? Còn tiền thì sao? Anh đã đưa đủ chưa?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "嗯？你给他们多少钱？是没给够吗？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Häh? Was ist mit dem Geld? Hast du sichergestellt, dass du ihnen den richtigen Betrag gegeben hast?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Hein ? Et l'argent ? Tu lui as pas donné l'enveloppe ?"
L16_1.m_Talk_FRA = L17_1
