L19_1 = "GRONIA_ACT3_INTERLUDE1@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 4100301
L18_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "SOLDIER_GRONIA_NULL_C"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "이것들, 용병들이랍시고 세상 모르고 설치는군."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "こいつら、傭兵だからってなんでも許されると思ってるな。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Look, you mercenaries don’t seem to know how the world works."
L18_1.m_Talk_ENG = L19_1
L19_1 = "你們這些傭兵真是不長眼睛！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ดูทำเข้า ทหารรับจ้างอย่างแกนี่ดูจะไม่เป็นงานเลยนะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nhìn xem, những tên lính đánh thuê dường như không biết thế giới hoạt động như thế nào."
L18_1.m_Talk_VTN = L19_1
L19_1 = "你们这些臭佣兵，别太嚣张。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ihr Söldner scheint echt nicht zu wissen, wie die Welt funktioniert."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Non mais franchement... dans quel monde vous vivez, les mercenaires ?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "GRONIA_ACT3_INTERLUDE1@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 4100301
L19_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "m_BGCrash"
L19_1[L20_1] = 20
L20_1 = "m_fBGCrashTime"
L19_1[L20_1] = 0.5
L20_1 = "SOLDIER_GRONIA_NULL_C"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "m_Crash"
L19_1[L20_1] = 20
L20_1 = "뇌물공여는 중죄라는 걸 모르나? 전부 차에서 내려!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "贈賄は重罪であることを知らないのか？　全員車から降りろ！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Aren’t you even aware that bribery is a felony? Everybody, out of the car, now!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "難道不知道賄賂是重罪嗎？立刻給我下車！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ไม่ได้รู้เลยรึไงว่าติดสินบนมันเป็นอาชญากรรมน่ะ? ทุกคน ออกมาจากรถเดี๋ยวนี้!"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cậu không biết rằng hối lộ là một trọng tội sao? Mọi người ra khỏi xe ngay!"
L19_1.m_Talk_VTN = L20_1
L20_1 = "难道不知道行贿是重罪吗？全都给我下车！"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ist euch überhaupt bewusst, dass Bestechung ein Verbrechen ist? Alle, raus dem Auto!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "On ne vous a jamais dit que la corruption est un crime ? Tout le monde descend, mains sur la tête !"
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
