L20_1.m_Pos = "C"
L21_1 = "떽떽거리지 마. 총각."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "つべこべうるさいぞ。若造。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Shh, quiet down, young man."
L20_1.m_Talk_ENG = L21_1
L21_1 = "小夥子，少在那邊大呼小叫的！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ชู่ว เบาๆ ก็ได้ ไอ้หนุ่ม"
L20_1.m_Talk_THA = L21_1
L21_1 = "Suỵt, im lặng đi, chàng trai trẻ."
L20_1.m_Talk_VTN = L21_1
L21_1 = "年轻人真是啰嗦。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Tzz, ganz ruhig, junger Mann."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Tout doux, jeune homme."
L20_1.m_Talk_FRA = L21_1
