L23_1[L24_1] = 20
L24_1 = "비, 비상! 비상! 당장 상부에 연락……!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ひ、非常事態！　非常事態だ！　今すぐ上層部に連絡を……！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Em-Emergency! It’s an emergency! Call for backup—!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "注…注意！緊急狀況！立刻通報上……！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฉะ-ฉุกเฉิน! เกิดเหตุฉุกเฉิน! เรียกกำลังเสริม...!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Kh-Khẩn cấp! Đây là một trường hợp khẩn cấp! Gọi cho hỗ trợ...!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "紧、紧急！紧急情况！快通知上级……！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "N-Notfall! Es ist ein Notfall! Fordere Unterstützung an ...!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "U-Urgence ! Urgence ! Appelez des renf... !"
L23_1.m_Talk_FRA = L24_1
