L35_1 = "THEMA_DIVE_BOTTOM"
L34_1.m_StartBGMFileName = L35_1
L35_1 = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL_02"
L34_1.m_StartFXSoundName = L35_1
L35_1 = "MONTAGNE_ADMIN_NULL_SNIPER"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "뭘 굽실거리고 앉았어. 반군이란 녀석이."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "何へいこらしてる。反乱軍なんだろう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "What were you going on about? Rebel scum."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你不是叛軍嗎？幹嘛在那邊低聲下氣的！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คิดจะทำอะไรของพวกแก? ไอ้กบฏสวะนี่"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tụi bây vừa làm gì thế? Lũ phiến quân cặn bã."
L34_1.m_Talk_VTN = L35_1
L35_1 = "低声下气地干什么，你不是叛军吗？"
L34_1.m_Talk_SCN = L35_1
L35_1 = " Du musst Dich nicht so verhalten. Du Rebellenabschaum."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Qu'est-ce que tu fais plantée là, le rebelle ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "GRONIA_ACT3_INTERLUDE1@185#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 185
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 4100301
L35_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "MONTAGNE_ADMIN_NULL_SNIPER"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "어차피 지금은 침식체 때문에 이런 데 신경도 못 써. 얼른 차에 타."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "どうせ今は侵食体のおかげでこんな所には気も止めない。早く車に乗れ。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Anyways, because of Corrupted Objects, there’s no need to do this quietly. Quick. Get in the car."
L35_1.m_Talk_ENG = L36_1
L36_1 = "反正政府那邊正忙著應付侵蝕體，才沒多餘的心思管這裡。快上車！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่ยังไงก็เถอะ เพราะวัตถุคอร์รัปต์ เราเลยไม่ต้องทำกันเงียบๆ แล้ว เร็วเข้า ขึ้นรถ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Dù sao, bởi vì lũ Vật Thể Ăn Mòn, không cần phải làm chuyện này một cách lặng lẽ. Nhanh. Lên xe đi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "反正现在因为侵蚀体的攻击，他们没空顾及我们，快上车。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Auf jeden Fall müssen wir aufgrund der Counterside-Objekte nicht so leise sein. Schnell. Steigt ins Auto."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Vu l'agitation créée par les Objets corrompus, on peut laisser tomber la discrétion. Allez, en route."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
