L41_1.m_Talk_TWN = L42_1
L42_1 = "แหะแหะแหะ... ก็หลายคนอยู่นะนี่"
L41_1.m_Talk_THA = L42_1
L42_1 = "He, he he... Có khá nhiều người trong số này."
L41_1.m_Talk_VTN = L42_1
L42_1 = "嘿、嘿嘿……我是觉得他们人有点多。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Hehehe ... Es gibt ziemlich viele dieser Kerle."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Hé, hé hé... Ils étaient plutôt nombreux, ces types..."
