L43_1 = "한 발에 한 놈씩 해치우다니, 굉장하잖아."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "一人一発ずつでやるなんて、すごいな。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "One shot, one kill for each of them. Incredible."
L42_1.m_Talk_ENG = L43_1
L43_1 = "你一發子彈就幹掉一個欸，超威的！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "หนึ่งนัดหนึ่งศพทุกราย ไม่ธรรมดาจริงๆ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Bắn một phát, hạ một mạng. Thật đáng kinh ngạc."
L42_1.m_Talk_VTN = L43_1
L43_1 = "您一枪一个，真是厉害啊。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ein Typ nach dem anderen kriegt eine Kugel ab. Unglaublich."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Boum ! Un tir, un mort... T'es vraiment incroyable, toi !"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "GRONIA_ACT3_INTERLUDE1@193#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 193
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 4100301
L43_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L44_1 = "MONTAGNE_ADMIN_NULL_SNIPER"
L43_1.m_CharStrID = L44_1
L44_1 = "R"
L43_1.m_Pos = L44_1
L44_1 = "내 친구들은 다들 눈 감고도 하던 일이야. 운전이나 제대로 해."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "私の知り合いはみんな目をつむった状態でもやれたことだ。ちゃんと運転しろ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "My other friends could have taken care of something like this with their eyes closed. Just drive."
L43_1.m_Talk_ENG = L44_1
L44_1 = "這點小事我那些朋友閉著眼睛也辦得到，開你的車吧。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เพื่อนฉันคนอื่นๆ จัดการอะไรแบบนี้ได้ในพริบตาเดียวเท่านั้นแหละ ขับไป"
L43_1.m_Talk_THA = L44_1
L44_1 = "Những người bạn khác của tôi chỉ cần nhắm mắt cũng có thể giải quyết những việc như thế này. Cứ lái xe đi."
L43_1.m_Talk_VTN = L44_1
L44_1 = "这种小事，我的同伴们闭着眼睛都能做好。你还是好好开车吧。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Meine anderen Freunde hätten sich mit geschlossenen Augen um so etwas kümmern können. Fahr einfach."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Mes amis se seraient occupés de ces vermines les yeux fermés. Garde un œil sur la route, ok ?"
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "GRONIA_ACT3_INTERLUDE1@194#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 194
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 4100301
L44_1.m_CutScenStrID = "GRONIA_ACT3_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "ROGUE_EXTRA_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "L"
L44_1.m_Pos = L45_1
L45_1 = "헤헤, 꽉 잡으라고. 신나게 밟을 테니까."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "へへ、しっかり掴まってろよ。思いっきり飛ばすから。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Heh heh... Hold on tight. Let’s see how fast this thing can go."
L44_1.m_Talk_ENG = L45_1
L45_1 = "嘿嘿，抓緊囉，我要加速囉！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "แหะแหะ... จับให้แน่ล่ะ มาดูกันเถอะว่าเจ้านี่จะเร็วขนาดไหน"
L44_1.m_Talk_THA = L45_1
L45_1 = "He he... Ngồi cho chắc vào. Để xem thứ này có thể đi nhanh như thế nào."
L44_1.m_Talk_VTN = L45_1
L45_1 = "嘿嘿。那您抓稳了。我要开足马力啦。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Hehehe ... Gut festhalten. Mal sehen, wie schnell dieses Ding fahren kann."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Hé hé... Tu ferais mieux de t'accrocher, parce que je suis un as du volant."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
